INSERT INTO learning_courses (id, title, summary, category, level, profession_ids, provider, source_title, source_url, video_id, image_path, visual_prompt, prerequisites, outcomes) VALUES
('python-foundations', '{"en":"Python: from first program to useful tools","ar":"بايثون: من البرنامج الأول إلى أدوات مفيدة"}', '{"en":"A complete beginner video course with a practical guide to functions, collections and reliable input handling.","ar":"دورة فيديو كاملة للمبتدئين مع دليل عملي للدوال والمجموعات ومعالجة المدخلات بشكل موثوق."}', 'systems', 'beginner', '["backend-engineer","data-engineer","ml-engineer","ai-researcher"]', 'freeCodeCamp.org', 'Learn Python - Full Course for Beginners [Tutorial]', 'https://www.youtube.com/watch?v=rfscVS0vtbw', 'rfscVS0vtbw', '/images/careers/backend-engineer.jpg', '{"en":"Create a 16:9 educational diagram for \"Python: from first program to useful tools\". Explain Values, types and decisions and Collections and reusable functions and Files, errors and reproducibility. Show inputs, decisions and outputs, then a small example from \"Build an expense summarizer\". Use numbered annotations, clear vector shapes, forest-green accents and accessible contrast. Label in English. No invented statistics or provider logos.","ar":"صمّم مخططاً تعليمياً بنسبة 16:9 لدورة «بايثون: من البرنامج الأول إلى أدوات مفيدة». اشرح القيم والأنواع والقرارات والمجموعات والدوال القابلة لإعادة الاستخدام والملفات والأخطاء وقابلية التكرار. وضّح المدخلات والقرارات والمخرجات ثم مثالاً من «ابنِ ملخصاً للمصروفات». استخدم تعليقات مرقمة وأشكالاً متجهة واضحة ولمسات خضراء وتبايناً مقروءاً وتسميات عربية. دون إحصاءات مختلقة أو شعارات الجهات."}', '{"en":"No programming experience required. Install Python 3 and a text editor to complete the exercises.","ar":"لا تحتاج إلى خبرة برمجية. ثبّت بايثون 3 ومحرر نصوص لتنفيذ التمارين."}', '[{"en":"Values, types and decisions","ar":"القيم والأنواع والقرارات"},{"en":"Collections and reusable functions","ar":"المجموعات والدوال القابلة لإعادة الاستخدام"},{"en":"Files, errors and reproducibility","ar":"الملفات والأخطاء وقابلية التكرار"}]'),
('computer-science', '{"en":"Computer science with Harvard CS50","ar":"علوم الحاسوب مع Harvard CS50"}', '{"en":"Explore the complete CS50 video, then practice algorithmic reasoning, memory and web fundamentals.","ar":"شاهد فيديو CS50 الكامل ثم طبّق التفكير الخوارزمي ومفاهيم الذاكرة وأساسيات الويب."}', 'systems', 'beginner', '["backend-engineer","mobile-engineer","blockchain-engineer"]', 'freeCodeCamp.org', 'Harvard CS50 – Full Computer Science University Course', 'https://www.youtube.com/watch?v=8mAITcNt710', '8mAITcNt710', '/images/careers/backend-engineer.jpg', '{"en":"Create a 16:9 educational diagram for \"Computer science with Harvard CS50\". Explain Algorithms and representation and Data structures and complexity and From memory to web systems. Show inputs, decisions and outputs, then a small example from \"Compare two search algorithms\". Use numbered annotations, clear vector shapes, forest-green accents and accessible contrast. Label in English. No invented statistics or provider logos.","ar":"صمّم مخططاً تعليمياً بنسبة 16:9 لدورة «علوم الحاسوب مع Harvard CS50». اشرح الخوارزميات وتمثيل البيانات وهياكل البيانات والتعقيد ومن الذاكرة إلى أنظمة الويب. وضّح المدخلات والقرارات والمخرجات ثم مثالاً من «قارن خوارزميتي بحث». استخدم تعليقات مرقمة وأشكالاً متجهة واضحة ولمسات خضراء وتبايناً مقروءاً وتسميات عربية. دون إحصاءات مختلقة أو شعارات الجهات."}', '{"en":"Comfort using a computer; no prior programming required. The video is long: study it across several sessions.","ar":"إجادة استخدام الحاسوب دون اشتراط خبرة برمجية. الفيديو طويل؛ قسم مشاهدته إلى جلسات متعددة."}', '[{"en":"Algorithms and representation","ar":"الخوارزميات وتمثيل البيانات"},{"en":"Data structures and complexity","ar":"هياكل البيانات والتعقيد"},{"en":"From memory to web systems","ar":"من الذاكرة إلى أنظمة الويب"}]'),
('javascript-foundations', '{"en":"JavaScript programming foundations","ar":"أساسيات البرمجة بجافاسكربت"}', '{"en":"A complete introduction to JavaScript with focused practice in functions, objects and transformations.","ar":"مقدمة كاملة لجافاسكربت مع تدريب على الدوال والكائنات وتحويل البيانات."}', 'systems', 'beginner', '["backend-engineer","mobile-engineer","blockchain-engineer"]', 'freeCodeCamp.org', 'Learn JavaScript - Full Course for Beginners', 'https://www.youtube.com/watch?v=PkZNo7MFNFg', 'PkZNo7MFNFg', '/images/careers/backend-engineer.jpg', '{"en":"Create a 16:9 educational diagram for \"JavaScript programming foundations\". Explain Scope, values and equality and Functions and collection transformations and Validate boundaries. Show inputs, decisions and outputs, then a small example from \"Build a job shortlist\". Use numbered annotations, clear vector shapes, forest-green accents and accessible contrast. Label in English. No invented statistics or provider logos.","ar":"صمّم مخططاً تعليمياً بنسبة 16:9 لدورة «أساسيات البرمجة بجافاسكربت». اشرح النطاق والقيم والمساواة والدوال وتحويل المجموعات وتحقق من حدود البيانات. وضّح المدخلات والقرارات والمخرجات ثم مثالاً من «ابنِ قائمة وظائف مختارة». استخدم تعليقات مرقمة وأشكالاً متجهة واضحة ولمسات خضراء وتبايناً مقروءاً وتسميات عربية. دون إحصاءات مختلقة أو شعارات الجهات."}', '{"en":"A browser console or a recent Node.js installation. No framework knowledge is required.","ar":"وحدة تحكم المتصفح أو إصدار حديث من Node.js، دون الحاجة إلى معرفة إطار عمل."}', '[{"en":"Scope, values and equality","ar":"النطاق والقيم والمساواة"},{"en":"Functions and collection transformations","ar":"الدوال وتحويل المجموعات"},{"en":"Validate boundaries","ar":"تحقق من حدود البيانات"}]'),
('sql-data', '{"en":"SQL and relational data","ar":"SQL والبيانات العلائقية"}', '{"en":"Learn the complete SQL video course and build a small, queryable recruitment dataset.","ar":"تعلّم من دورة SQL الكاملة وابنِ مجموعة بيانات توظيف صغيرة قابلة للاستعلام."}', 'data', 'intermediate', '["data-engineer","backend-engineer"]', 'freeCodeCamp.org', 'SQL Tutorial - Full Database Course for Beginners', 'https://www.youtube.com/watch?v=HXV3zeQKqGY', 'HXV3zeQKqGY', '/images/careers/data-engineer.jpg', '{"en":"Create a 16:9 educational diagram for \"SQL and relational data\". Explain Model records and relationships and Query, join and aggregate and Change data safely. Show inputs, decisions and outputs, then a small example from \"Create a recruitment dataset\". Use numbered annotations, clear vector shapes, forest-green accents and accessible contrast. Label in English. No invented statistics or provider logos.","ar":"صمّم مخططاً تعليمياً بنسبة 16:9 لدورة «SQL والبيانات العلائقية». اشرح نمذجة السجلات والعلاقات والاستعلام والربط والتجميع وتعديل البيانات بشكل موثوق. وضّح المدخلات والقرارات والمخرجات ثم مثالاً من «أنشئ بيانات توظيف». استخدم تعليقات مرقمة وأشكالاً متجهة واضحة ولمسات خضراء وتبايناً مقروءاً وتسميات عربية. دون إحصاءات مختلقة أو شعارات الجهات."}', '{"en":"Basic data concepts. Use a local practice database with fictional records.","ar":"مفاهيم أولية عن البيانات. استخدم قاعدة تدريب محلية بسجلات افتراضية."}', '[{"en":"Model records and relationships","ar":"نمذجة السجلات والعلاقات"},{"en":"Query, join and aggregate","ar":"الاستعلام والربط والتجميع"},{"en":"Change data safely","ar":"تعديل البيانات بشكل موثوق"}]'),
('machine-learning', '{"en":"Machine learning: evaluate before you deploy","ar":"تعلم الآلة: قيّم قبل النشر"}', '{"en":"Study a complete introductory ML course, then practice splitting data and comparing a model with a baseline.","ar":"ادرس دورة كاملة في أساسيات تعلم الآلة ثم تدرب على تقسيم البيانات ومقارنة النموذج بخط أساس."}', 'ai', 'intermediate', '["ml-engineer","ai-researcher","data-engineer"]', 'freeCodeCamp.org', 'Machine Learning for Everybody – Full Course', 'https://www.youtube.com/watch?v=i_LwzRVP7bg', 'i_LwzRVP7bg', '/images/careers/ml-engineer.jpg', '{"en":"Create a 16:9 educational diagram for \"Machine learning: evaluate before you deploy\". Explain Frame a prediction problem and Separate training from evaluation and Use metrics and baselines. Show inputs, decisions and outputs, then a small example from \"Build a reproducible baseline\". Use numbered annotations, clear vector shapes, forest-green accents and accessible contrast. Label in English. No invented statistics or provider logos.","ar":"صمّم مخططاً تعليمياً بنسبة 16:9 لدورة «تعلم الآلة: قيّم قبل النشر». اشرح صياغة مشكلة التنبؤ وفصل التدريب عن التقييم واستخدام المقاييس وخطوط الأساس. وضّح المدخلات والقرارات والمخرجات ثم مثالاً من «ابنِ خط أساس قابلًا للتكرار». استخدم تعليقات مرقمة وأشكالاً متجهة واضحة ولمسات خضراء وتبايناً مقروءاً وتسميات عربية. دون إحصاءات مختلقة أو شعارات الجهات."}', '{"en":"Basic Python, arithmetic and familiarity with tabular data.","ar":"أساسيات بايثون والحساب والتعامل مع البيانات الجدولية."}', '[{"en":"Frame a prediction problem","ar":"صياغة مشكلة التنبؤ"},{"en":"Separate training from evaluation","ar":"فصل التدريب عن التقييم"},{"en":"Use metrics and baselines","ar":"استخدام المقاييس وخطوط الأساس"}]'),
('pytorch-deep-learning', '{"en":"Deep learning with PyTorch","ar":"التعلم العميق باستخدام PyTorch"}', '{"en":"A complete long-form PyTorch course with a study companion on training loops, evaluation and reproducible experiments.","ar":"دورة PyTorch كاملة وطويلة مع دليل لحلقات التدريب والتقييم والتجارب القابلة للتكرار."}', 'ai', 'advanced', '["ml-engineer","ai-researcher"]', 'Daniel Bourke', 'Learn PyTorch for deep learning in a day. Literally.', 'https://www.youtube.com/watch?v=Z_ikDlimN6A', 'Z_ikDlimN6A', '/images/careers/ml-engineer.jpg', '{"en":"Create a 16:9 educational diagram for \"Deep learning with PyTorch\". Explain Tensors, shapes and devices and The training loop and Evaluation and experiment records. Show inputs, decisions and outputs, then a small example from \"Train a compact classifier\". Use numbered annotations, clear vector shapes, forest-green accents and accessible contrast. Label in English. No invented statistics or provider logos.","ar":"صمّم مخططاً تعليمياً بنسبة 16:9 لدورة «التعلم العميق باستخدام PyTorch». اشرح الموترات والأبعاد والأجهزة وحلقة التدريب والتقييم وتوثيق التجارب. وضّح المدخلات والقرارات والمخرجات ثم مثالاً من «درّب مصنفاً صغيراً». استخدم تعليقات مرقمة وأشكالاً متجهة واضحة ولمسات خضراء وتبايناً مقروءاً وتسميات عربية. دون إحصاءات مختلقة أو شعارات الجهات."}', '{"en":"Python, tensors, basic ML evaluation and an environment with PyTorch installed. A GPU is optional for a small project.","ar":"بايثون والموترات وتقييم تعلم الآلة وبيئة تحتوي PyTorch. بطاقة رسومية اختيارية للمشروع الصغير."}', '[{"en":"Tensors, shapes and devices","ar":"الموترات والأبعاد والأجهزة"},{"en":"The training loop","ar":"حلقة التدريب"},{"en":"Evaluation and experiment records","ar":"التقييم وتوثيق التجارب"}]'),
('google-cloud', '{"en":"Google Cloud infrastructure","ar":"البنية التحتية على Google Cloud"}', '{"en":"Study cloud infrastructure through a complete Associate Cloud Engineer preparation video and a system-design exercise.","ar":"ادرس البنية السحابية عبر فيديو كامل للاستعداد لمهندس السحابة المساعد وتمرين لتصميم نظام."}', 'cloud', 'intermediate', '["cloud-architect","devops-engineer"]', 'freeCodeCamp.org', 'Google Cloud Associate Cloud Engineer Course - Pass the Exam!', 'https://www.youtube.com/watch?v=jpno8FSqpc8', 'jpno8FSqpc8', '/images/careers/cloud-architect.jpg', '{"en":"Create a 16:9 educational diagram for \"Google Cloud infrastructure\". Explain Resource boundaries and identity and Choose services by workload. Show inputs, decisions and outputs, then a small example from \"Design a small learning platform\". Use numbered annotations, clear vector shapes, forest-green accents and accessible contrast. Label in English. No invented statistics or provider logos.","ar":"صمّم مخططاً تعليمياً بنسبة 16:9 لدورة «البنية التحتية على Google Cloud». اشرح حدود الموارد والهوية واختيار الخدمات بحسب الحمل. وضّح المدخلات والقرارات والمخرجات ثم مثالاً من «صمّم منصة تعلم صغيرة». استخدم تعليقات مرقمة وأشكالاً متجهة واضحة ولمسات خضراء وتبايناً مقروءاً وتسميات عربية. دون إحصاءات مختلقة أو شعارات الجهات."}', '{"en":"Basic networking and command-line knowledge. Exercises can be completed as diagrams without a paid cloud account. The recording may use older console screens.","ar":"أساسيات الشبكات وسطر الأوامر. يمكن إتمام التمارين كمخططات دون حساب سحابي مدفوع. قد يعرض التسجيل واجهات تحكم أقدم."}', '[{"en":"Resource boundaries and identity","ar":"حدود الموارد والهوية"},{"en":"Choose services by workload","ar":"اختيار الخدمات بحسب الحمل"}]'),
('docker', '{"en":"Docker: package and run applications","ar":"Docker: تحزيم التطبيقات وتشغيلها"}', '{"en":"A complete Docker introduction supported by a practical guide to images, containers and durable data.","ar":"مقدمة كاملة في Docker مع دليل عملي للصور والحاويات والبيانات الدائمة."}', 'cloud', 'beginner', '["devops-engineer","backend-engineer","cloud-architect"]', 'freeCodeCamp.org', 'Docker Tutorial for Beginners - A Full DevOps Course on How to Run Applications in Containers', 'https://www.youtube.com/watch?v=fqMOX6JJhGo', 'fqMOX6JJhGo', '/images/careers/devops-engineer.jpg', '{"en":"Create a 16:9 educational diagram for \"Docker: package and run applications\". Explain Images and running containers and Ports, volumes and configuration. Show inputs, decisions and outputs, then a small example from \"Containerize a small service\". Use numbered annotations, clear vector shapes, forest-green accents and accessible contrast. Label in English. No invented statistics or provider logos.","ar":"صمّم مخططاً تعليمياً بنسبة 16:9 لدورة «Docker: تحزيم التطبيقات وتشغيلها». اشرح الصور والحاويات المشغلة والمنافذ ووحدات التخزين والإعدادات. وضّح المدخلات والقرارات والمخرجات ثم مثالاً من «ضع خدمة صغيرة في حاوية». استخدم تعليقات مرقمة وأشكالاً متجهة واضحة ولمسات خضراء وتبايناً مقروءاً وتسميات عربية. دون إحصاءات مختلقة أو شعارات الجهات."}', '{"en":"Basic terminal commands and a small application. Docker is needed only for the practical exercise.","ar":"أوامر الطرفية الأساسية وتطبيق صغير. تحتاج Docker للتمرين العملي فقط."}', '[{"en":"Images and running containers","ar":"الصور والحاويات المشغلة"},{"en":"Ports, volumes and configuration","ar":"المنافذ ووحدات التخزين والإعدادات"}]'),
('kubernetes', '{"en":"Kubernetes application operations","ar":"تشغيل التطبيقات باستخدام Kubernetes"}', '{"en":"Study the complete Kubernetes video and design a resilient deployment with health checks and controlled rollouts.","ar":"ادرس فيديو Kubernetes الكامل وصمّم نشراً مرناً بفحوص صحة وتحديثات مدروسة."}', 'cloud', 'advanced', '["devops-engineer","cloud-architect"]', 'TechWorld with Nana', 'Kubernetes Tutorial for Beginners [FULL COURSE in 4 Hours]', 'https://www.youtube.com/watch?v=X48VuDVv0do', 'X48VuDVv0do', '/images/careers/devops-engineer.jpg', '{"en":"Create a 16:9 educational diagram for \"Kubernetes application operations\". Explain Desired state and reconciliation and Health and controlled delivery. Show inputs, decisions and outputs, then a small example from \"Design a resilient deployment\". Use numbered annotations, clear vector shapes, forest-green accents and accessible contrast. Label in English. No invented statistics or provider logos.","ar":"صمّم مخططاً تعليمياً بنسبة 16:9 لدورة «تشغيل التطبيقات باستخدام Kubernetes». اشرح الحالة المطلوبة والمصالحة والصحة والتسليم المدروس. وضّح المدخلات والقرارات والمخرجات ثم مثالاً من «صمّم نشراً مرناً». استخدم تعليقات مرقمة وأشكالاً متجهة واضحة ولمسات خضراء وتبايناً مقروءاً وتسميات عربية. دون إحصاءات مختلقة أو شعارات الجهات."}', '{"en":"Comfort with containers, networking and YAML. The video introduces Kubernetes; this pathway adds an advanced operations exercise.","ar":"إجادة الحاويات والشبكات وYAML. يقدّم الفيديو Kubernetes، ويضيف هذا المسار تمرين تشغيل متقدماً."}', '[{"en":"Desired state and reconciliation","ar":"الحالة المطلوبة والمصالحة"},{"en":"Health and controlled delivery","ar":"الصحة والتسليم المدروس"}]'),
('linux', '{"en":"Linux and command-line foundations","ar":"أساسيات لينكس وسطر الأوامر"}', '{"en":"A full Linux course with a study guide to files, permissions, processes and system observation.","ar":"دورة لينكس كاملة مع دليل للملفات والصلاحيات والعمليات ومراقبة النظام."}', 'security', 'beginner', '["security-analyst","devops-engineer","cloud-architect"]', 'freeCodeCamp.org', 'Introduction to Linux – Full Course for Beginners', 'https://www.youtube.com/watch?v=sWbUDq4S6Y8', 'sWbUDq4S6Y8', '/images/careers/security-analyst.jpg', '{"en":"Create a 16:9 educational diagram for \"Linux and command-line foundations\". Explain Files, streams and composition and Permissions and processes. Show inputs, decisions and outputs, then a small example from \"Inspect a practice system\". Use numbered annotations, clear vector shapes, forest-green accents and accessible contrast. Label in English. No invented statistics or provider logos.","ar":"صمّم مخططاً تعليمياً بنسبة 16:9 لدورة «أساسيات لينكس وسطر الأوامر». اشرح الملفات والتدفقات والتركيب والصلاحيات والعمليات. وضّح المدخلات والقرارات والمخرجات ثم مثالاً من «افحص نظام تدريب». استخدم تعليقات مرقمة وأشكالاً متجهة واضحة ولمسات خضراء وتبايناً مقروءاً وتسميات عربية. دون إحصاءات مختلقة أو شعارات الجهات."}', '{"en":"A disposable local Linux environment or virtual machine for practice.","ar":"بيئة لينكس محلية قابلة للاستبدال أو آلة افتراضية للتدريب."}', '[{"en":"Files, streams and composition","ar":"الملفات والتدفقات والتركيب"},{"en":"Permissions and processes","ar":"الصلاحيات والعمليات"}]'),
('security-labs', '{"en":"Security fundamentals and ethical practice","ar":"أساسيات الأمن والممارسة الأخلاقية"}', '{"en":"A complete ethical-hacking video paired with a defensive study guide and an isolated lab-report exercise.","ar":"فيديو كامل للاختبار الأخلاقي مع دليل دفاعي وتمرين تقرير مختبر معزول."}', 'security', 'intermediate', '["security-analyst"]', 'The Cyber Mentors', 'Ethical Hacking in 12 Hours - Full Course - Learn to Hack!', 'https://www.youtube.com/watch?v=fNzpcB7ODxQ', 'fNzpcB7ODxQ', '/images/careers/security-analyst.jpg', '{"en":"Create a 16:9 educational diagram for \"Security fundamentals and ethical practice\". Explain Scope and evidence and Risk and remediation. Show inputs, decisions and outputs, then a small example from \"Create an authorized lab plan\". Use numbered annotations, clear vector shapes, forest-green accents and accessible contrast. Label in English. No invented statistics or provider logos.","ar":"صمّم مخططاً تعليمياً بنسبة 16:9 لدورة «أساسيات الأمن والممارسة الأخلاقية». اشرح النطاق والأدلة والمخاطر والمعالجة. وضّح المدخلات والقرارات والمخرجات ثم مثالاً من «أنشئ خطة مختبر مصرح». استخدم تعليقات مرقمة وأشكالاً متجهة واضحة ولمسات خضراء وتبايناً مقروءاً وتسميات عربية. دون إحصاءات مختلقة أو شعارات الجهات."}', '{"en":"Linux and networking fundamentals. Practical activity is limited to systems you own or have explicit permission to test.","ar":"أساسيات لينكس والشبكات. يقتصر التطبيق على أنظمة تملكها أو لديك إذن صريح لاختبارها."}', '[{"en":"Scope and evidence","ar":"النطاق والأدلة"},{"en":"Risk and remediation","ar":"المخاطر والمعالجة"}]'),
('figma-design', '{"en":"UI/UX: from wireframe to prototype","ar":"تصميم الواجهات والتجربة: من التخطيط إلى النموذج"}', '{"en":"A complete Figma design tutorial with an original workflow for research, interaction and accessible prototypes.","ar":"شرح تصميم كامل باستخدام Figma مع منهج للبحث والتفاعل والنماذج القابلة للوصول."}', 'design', 'beginner', '["product-designer"]', 'freeCodeCamp.org', 'UI / UX Design Tutorial – Wireframe, Mockup & Design in Figma', 'https://www.youtube.com/watch?v=c9Wg6Cb_YlU', 'c9Wg6Cb_YlU', '/images/careers/product-designer.jpg', '{"en":"Create a 16:9 educational diagram for \"UI/UX: from wireframe to prototype\". Explain Start with the user task and Components and accessible interaction. Show inputs, decisions and outputs, then a small example from \"Design a course enrollment flow\". Use numbered annotations, clear vector shapes, forest-green accents and accessible contrast. Label in English. No invented statistics or provider logos.","ar":"صمّم مخططاً تعليمياً بنسبة 16:9 لدورة «تصميم الواجهات والتجربة: من التخطيط إلى النموذج». اشرح ابدأ بمهمة المستخدم والمكونات والتفاعل القابل للوصول. وضّح المدخلات والقرارات والمخرجات ثم مثالاً من «صمّم مسار الالتحاق بدورة». استخدم تعليقات مرقمة وأشكالاً متجهة واضحة ولمسات خضراء وتبايناً مقروءاً وتسميات عربية. دون إحصاءات مختلقة أو شعارات الجهات."}', '{"en":"A Figma account is useful for the exercise; paper sketches work for the first stage.","ar":"يفيد حساب Figma للتطبيق؛ وتكفي الرسوم الورقية للمرحلة الأولى."}', '[{"en":"Start with the user task","ar":"ابدأ بمهمة المستخدم"},{"en":"Components and accessible interaction","ar":"المكونات والتفاعل القابل للوصول"}]'),
('kotlin-mobile', '{"en":"Kotlin foundations for mobile engineers","ar":"أساسيات Kotlin لمهندسي الجوال"}', '{"en":"A complete Kotlin programming course with exercises on null safety, data models and state transitions.","ar":"دورة Kotlin كاملة مع تمارين على أمان القيم الفارغة ونماذج البيانات وانتقالات الحالة."}', 'mobile', 'beginner', '["mobile-engineer"]', 'freeCodeCamp.org', 'Learn Kotlin Programming – Full Course for Beginners', 'https://www.youtube.com/watch?v=EExSSotojVI', 'EExSSotojVI', '/images/careers/mobile-engineer.jpg', '{"en":"Create a 16:9 educational diagram for \"Kotlin foundations for mobile engineers\". Explain Nullability and explicit models and Functions and immutable transformations. Show inputs, decisions and outputs, then a small example from \"Model a learning screen\". Use numbered annotations, clear vector shapes, forest-green accents and accessible contrast. Label in English. No invented statistics or provider logos.","ar":"صمّم مخططاً تعليمياً بنسبة 16:9 لدورة «أساسيات Kotlin لمهندسي الجوال». اشرح القيم الفارغة والنماذج الصريحة والدوال والتحويلات دون تعديل الأصل. وضّح المدخلات والقرارات والمخرجات ثم مثالاً من «نمذج شاشة تعلم». استخدم تعليقات مرقمة وأشكالاً متجهة واضحة ولمسات خضراء وتبايناً مقروءاً وتسميات عربية. دون إحصاءات مختلقة أو شعارات الجهات."}', '{"en":"A Kotlin playground or local Kotlin environment. This is a language foundation, not a complete Android app-development certification.","ar":"بيئة Kotlin محلية أو ساحة تجريب. هذه أساسيات اللغة وليست شهادة متكاملة لتطوير أندرويد."}', '[{"en":"Nullability and explicit models","ar":"القيم الفارغة والنماذج الصريحة"},{"en":"Functions and immutable transformations","ar":"الدوال والتحويلات دون تعديل الأصل"}]'),
('blockchain-engineering', '{"en":"Solidity and full-stack Web3 engineering","ar":"Solidity وهندسة Web3 المتكاملة"}', '{"en":"A complete 32-hour publisher course with a companion on contract state, transactions and testing.","ar":"دورة كاملة مدتها 32 ساعة من الناشر مع دليل لحالة العقود والمعاملات والاختبار."}', 'blockchain', 'advanced', '["blockchain-engineer"]', 'freeCodeCamp.org', 'Learn Blockchain, Solidity, and Full Stack Web3 Development with JavaScript – 32-Hour Course', 'https://www.youtube.com/watch?v=gyMwXuJrbJQ', 'gyMwXuJrbJQ', '/images/careers/blockchain-engineer.jpg', '{"en":"Create a 16:9 educational diagram for \"Solidity and full-stack Web3 engineering\". Explain State, transactions and trust and Test invariants and access boundaries. Show inputs, decisions and outputs, then a small example from \"Build a local completion registry\". Use numbered annotations, clear vector shapes, forest-green accents and accessible contrast. Label in English. No invented statistics or provider logos.","ar":"صمّم مخططاً تعليمياً بنسبة 16:9 لدورة «Solidity وهندسة Web3 المتكاملة». اشرح الحالة والمعاملات والثقة واختبار الثوابت وحدود الوصول. وضّح المدخلات والقرارات والمخرجات ثم مثالاً من «ابنِ سجل إنجاز محلياً». استخدم تعليقات مرقمة وأشكالاً متجهة واضحة ولمسات خضراء وتبايناً مقروءاً وتسميات عربية. دون إحصاءات مختلقة أو شعارات الجهات."}', '{"en":"JavaScript and software testing fundamentals. Use a local development network and test accounts only; tooling in the recording may differ from current versions.","ar":"أساسيات جافاسكربت واختبار البرمجيات. استخدم شبكة تطوير محلية وحسابات اختبار فقط؛ قد تختلف أدوات التسجيل عن الإصدارات الحالية."}', '[{"en":"State, transactions and trust","ar":"الحالة والمعاملات والثقة"},{"en":"Test invariants and access boundaries","ar":"اختبار الثوابت وحدود الوصول"}]');
INSERT INTO learning_lessons (id, course_id, position, kind, title, content) VALUES
('python-foundations-watch', 'python-foundations', 0, 'video', '{"en":"Watch the complete source course","ar":"شاهد دورة المصدر كاملة"}', '{"introduction":{"en":"Play the complete publisher video here. Pause and resume with the player controls; lesson completion is marked manually after studying.","ar":"شغّل فيديو الناشر الكامل هنا. أوقف واستأنف من أدوات المشغل؛ توضع علامة إنجاز الدرس يدوياً بعد الدراسة."},"sections":[{"title":{"en":"Before watching","ar":"قبل المشاهدة"},"body":{"en":"No programming experience required. Install Python 3 and a text editor to complete the exercises.","ar":"لا تحتاج إلى خبرة برمجية. ثبّت بايثون 3 ومحرر نصوص لتنفيذ التمارين."}},{"title":{"en":"Study actively","ar":"ادرس بتفاعل"},"body":{"en":"Work through examples in your own environment rather than only watching. Write down unfamiliar terms and record useful timestamps in your notes. Explain each major idea without looking at the recording, then use the next lessons to consolidate and practice it.","ar":"نفّذ الأمثلة في بيئتك بدلاً من المشاهدة وحدها. دوّن المصطلحات الجديدة والأوقات المفيدة في ملاحظاتك. اشرح الأفكار الأساسية دون الرجوع للتسجيل، ثم استخدم الدروس التالية لترسيخها وتطبيقها."}}]}'),
('python-foundations-concepts', 'python-foundations', 1, 'reading', '{"en":"Understand the core concepts","ar":"افهم المفاهيم الأساسية"}', '{"introduction":{"en":"A complete beginner video course with a practical guide to functions, collections and reliable input handling.","ar":"دورة فيديو كاملة للمبتدئين مع دليل عملي للدوال والمجموعات ومعالجة المدخلات بشكل موثوق."},"sections":[{"title":{"en":"Values, types and decisions","ar":"القيم والأنواع والقرارات"},"body":{"en":"A variable binds a name to a value. Strings represent text; integers represent whole numbers. input() returns text even when a person types digits. Convert deliberately with int() or float(), and handle ValueError when conversion fails. Use if / elif / else to choose a branch. Test empty input and zero separately rather than assuming every value behaves like a positive number.","ar":"يربط المتغير اسماً بقيمة. تمثل السلاسل النصوص والأعداد الصحيحة القيم الكاملة. تعيد input() نصاً حتى عند كتابة أرقام. حوّل القيم صراحة باستخدام int() أو float()، وتعامل مع ValueError عند فشل التحويل. استخدم if وelif وelse لاختيار الفرع المناسب. اختبر النص الفارغ والصفر بشكل منفصل بدلاً من افتراض أن كل قيمة عدد موجب."}},{"title":{"en":"Collections and reusable functions","ar":"المجموعات والدوال القابلة لإعادة الاستخدام"},"body":{"en":"Use a list for ordered entries and a dictionary for lookup by key. A loop processes each entry without duplicating logic. Put one responsibility in each function: accept inputs as parameters and return a result instead of relying on global variables. Keep printing separate from calculation so the same function can serve a command-line tool, an API or a test.","ar":"استخدم القائمة للعناصر المرتبة والقاموس للوصول بالمفتاح. تعالج الحلقة كل عنصر دون تكرار المنطق. اجعل لكل دالة مسؤولية واحدة: مرّر المدخلات كمعاملات وأعد النتيجة بدلاً من الاعتماد على متغيرات عامة. افصل الطباعة عن الحساب كي تعمل الدالة نفسها في أداة سطر أوامر أو واجهة برمجية أو اختبار."}},{"title":{"en":"Files, errors and reproducibility","ar":"الملفات والأخطاء وقابلية التكرار"},"body":{"en":"Open a file with a context manager so it closes after use. Catch the specific errors you can recover from; a bare except can hide bugs. Describe dependencies and the command needed to run your program in a README. A small test that checks a known input and output is more valuable than manually trying only the happy path.","ar":"افتح الملف باستخدام مدير سياق كي يغلق بعد الاستخدام. التقط الأخطاء المحددة التي تستطيع معالجتها؛ فقد يخفي except العام عيوباً برمجية. دوّن الاعتماديات وأمر تشغيل البرنامج في README. اختبار صغير لمدخل وخرج معروفين أفضل من تجربة الحالة الناجحة وحدها يدوياً."}}]}'),
('python-foundations-practice', 'python-foundations', 2, 'practice', '{"en":"Build an expense summarizer","ar":"ابنِ ملخصاً للمصروفات"}', '{"introduction":{"en":"Turn the ideas into evidence of your understanding. Complete the exercise and keep a short explanation of your decisions.","ar":"حوّل الأفكار إلى دليل على فهمك. نفّذ التمرين واحتفظ بشرح موجز لقراراتك."},"sections":[{"title":{"en":"Build an expense summarizer","ar":"ابنِ ملخصاً للمصروفات"},"body":{"en":"Create a function that accepts a list of expense dictionaries with category and amount. Validate that each amount is numeric and nonnegative. Return totals grouped by category and a grand total. Start with three categories and at least six entries; do not embed business logic in input prompts.","ar":"أنشئ دالة تستقبل قائمة مصروفات تحتوي على الفئة والمبلغ. تحقق من أن كل مبلغ رقمي وغير سالب. أعد الإجمالي بحسب الفئة والإجمالي العام. ابدأ بثلاث فئات وستة عناصر على الأقل؛ ولا تضع منطق المعالجة داخل مطالبات الإدخال."}},{"title":{"en":"Verify and explain","ar":"تحقق واشرح"},"body":{"en":"Test an empty list, a zero amount, an invalid amount and repeated categories. Show the expected totals for a small fixture. Add a README with setup steps and one sample run. Explain why dictionaries are useful here and what you would change to support several currencies.","ar":"اختبر قائمة فارغة ومبلغاً صفرياً ومبلغاً غير صالح وفئات متكررة. وضّح الإجماليات المتوقعة لبيانات صغيرة. أضف README بخطوات التشغيل ومثال واحد. اشرح فائدة القواميس وما الذي تغيره لدعم عدة عملات."}}]}'),
('python-foundations-check', 'python-foundations', 3, 'quiz', '{"en":"Check your understanding","ar":"اختبر فهمك"}', '{"introduction":{"en":"Choose an answer for each question and check the explanations. You can retry; these checks support learning and do not issue a provider certificate.","ar":"اختر إجابة لكل سؤال وراجع التفسير. يمكنك إعادة المحاولة؛ تدعم هذه الأسئلة التعلم ولا تمنح شهادة من الجهة الأصلية."},"sections":[],"questions":[{"question":{"en":"What does input() return?","ar":"ماذا تعيد input()؟"},"options":[{"en":"Always an integer","ar":"عدداً صحيحاً دائماً"},{"en":"A string","ar":"سلسلة نصية"},{"en":"A dictionary","ar":"قاموساً"}],"answer":1,"explanation":{"en":"Convert the returned string explicitly when a number is required.","ar":"حوّل النص الناتج صراحة عند الحاجة إلى رقم."}},{"question":{"en":"Which design makes calculation easy to test?","ar":"أي تصميم يجعل اختبار الحساب سهلاً؟"},"options":[{"en":"A function that receives values and returns a result","ar":"دالة تستقبل قيماً وتعيد نتيجة"},{"en":"Reading global variables inside every function","ar":"قراءة متغيرات عامة داخل كل دالة"},{"en":"Catching all exceptions without reporting them","ar":"التقاط جميع الأخطاء دون الإبلاغ عنها"}],"answer":0,"explanation":{"en":"Explicit inputs and outputs isolate the calculation from the interface.","ar":"تعزل المدخلات والمخرجات الصريحة الحساب عن الواجهة."}}]}'),
('computer-science-watch', 'computer-science', 0, 'video', '{"en":"Watch the complete source course","ar":"شاهد دورة المصدر كاملة"}', '{"introduction":{"en":"Play the complete publisher video here. Pause and resume with the player controls; lesson completion is marked manually after studying.","ar":"شغّل فيديو الناشر الكامل هنا. أوقف واستأنف من أدوات المشغل؛ توضع علامة إنجاز الدرس يدوياً بعد الدراسة."},"sections":[{"title":{"en":"Before watching","ar":"قبل المشاهدة"},"body":{"en":"Comfort using a computer; no prior programming required. The video is long: study it across several sessions.","ar":"إجادة استخدام الحاسوب دون اشتراط خبرة برمجية. الفيديو طويل؛ قسم مشاهدته إلى جلسات متعددة."}},{"title":{"en":"Study actively","ar":"ادرس بتفاعل"},"body":{"en":"Work through examples in your own environment rather than only watching. Write down unfamiliar terms and record useful timestamps in your notes. Explain each major idea without looking at the recording, then use the next lessons to consolidate and practice it.","ar":"نفّذ الأمثلة في بيئتك بدلاً من المشاهدة وحدها. دوّن المصطلحات الجديدة والأوقات المفيدة في ملاحظاتك. اشرح الأفكار الأساسية دون الرجوع للتسجيل، ثم استخدم الدروس التالية لترسيخها وتطبيقها."}}]}'),
('computer-science-concepts', 'computer-science', 1, 'reading', '{"en":"Understand the core concepts","ar":"افهم المفاهيم الأساسية"}', '{"introduction":{"en":"Explore the complete CS50 video, then practice algorithmic reasoning, memory and web fundamentals.","ar":"شاهد فيديو CS50 الكامل ثم طبّق التفكير الخوارزمي ومفاهيم الذاكرة وأساسيات الويب."},"sections":[{"title":{"en":"Algorithms and representation","ar":"الخوارزميات وتمثيل البيانات"},"body":{"en":"An algorithm is a precise sequence of steps with defined inputs and outputs. The same information can have different representations: bytes, text, images or structured records. Start by specifying the problem and small examples before choosing a language. A clear algorithm should terminate and handle boundary inputs such as an empty collection.","ar":"الخوارزمية تسلسل دقيق من الخطوات بمدخلات ومخرجات محددة. يمكن تمثيل المعلومات نفسها كبايتات أو نصوص أو صور أو سجلات منظمة. ابدأ بتحديد المشكلة وأمثلة صغيرة قبل اختيار اللغة. ينبغي أن تنتهي الخوارزمية وتعالج الحالات الحدية مثل المجموعة الفارغة."}},{"title":{"en":"Data structures and complexity","ar":"هياكل البيانات والتعقيد"},"body":{"en":"An array offers indexed access; a linked structure trades direct indexing for different insertion and allocation behavior. Binary search requires sorted data and repeatedly halves the search range. Big-O describes how work grows with input size, not a guarantee of runtime in milliseconds. Compare algorithms using both correctness and the operations they perform.","ar":"تتيح المصفوفة وصولاً بالفهرس؛ بينما تختلف البنى المترابطة في الإدراج وتخصيص الذاكرة. يتطلب البحث الثنائي بيانات مرتبة ويقسم مجال البحث إلى نصفين. تصف Big-O نمو العمل مع حجم المدخلات، وليست ضماناً لزمن بالمللي ثانية. قارن الخوارزميات من حيث الصحة والعمليات التي تنفذها."}},{"title":{"en":"From memory to web systems","ar":"من الذاكرة إلى أنظمة الويب"},"body":{"en":"Memory has a lifetime: a value must remain valid while code uses it. Higher-level languages automate parts of memory management but do not remove the need to reason about references and state. In a web system, distinguish a browser interface, a server handling requests and a database storing records. Validate data at the server boundary even if the interface already validates it.","ar":"للذاكرة عمر استخدام؛ يجب أن تبقى القيمة صالحة ما دام الكود يستعملها. تؤتمت اللغات الأعلى مستوى أجزاء من إدارة الذاكرة دون إلغاء ضرورة فهم المراجع والحالة. ميّز في الويب بين واجهة المتصفح والخادم الذي يعالج الطلبات وقاعدة البيانات التي تحفظ السجلات. تحقق من البيانات عند حدود الخادم حتى مع التحقق في الواجهة."}}]}'),
('computer-science-practice', 'computer-science', 2, 'practice', '{"en":"Compare two search algorithms","ar":"قارن خوارزميتي بحث"}', '{"introduction":{"en":"Turn the ideas into evidence of your understanding. Complete the exercise and keep a short explanation of your decisions.","ar":"حوّل الأفكار إلى دليل على فهمك. نفّذ التمرين واحتفظ بشرح موجز لقراراتك."},"sections":[{"title":{"en":"Compare two search algorithms","ar":"قارن خوارزميتي بحث"},"body":{"en":"Implement linear search and binary search over a sorted list of integers. Count comparisons instead of measuring only wall-clock time. Run both on lists of increasing size and targets at the beginning, middle, end and outside the list.","ar":"نفّذ البحث الخطي والثنائي على قائمة أعداد مرتبة. احسب المقارنات بدلاً من قياس زمن التشغيل وحده. جرّبهما على قوائم متزايدة الحجم وأهداف في البداية والوسط والنهاية وخارج القائمة."}},{"title":{"en":"Document the tradeoff","ar":"وثّق المفاضلة"},"body":{"en":"Include tests for an empty list, one element and duplicate values. State whether your implementation returns any match or the first match. Explain why binary search is inappropriate on an unsorted list, and include the cost of sorting when comparing approaches.","ar":"أضف اختبارات للقائمة الفارغة والعنصر الواحد والقيم المتكررة. حدد هل يعيد التنفيذ أي تطابق أم أول تطابق. اشرح لماذا لا يناسب البحث الثنائي قائمة غير مرتبة، واحتسب تكلفة الترتيب عند المقارنة."}}]}'),
('computer-science-check', 'computer-science', 3, 'quiz', '{"en":"Check your understanding","ar":"اختبر فهمك"}', '{"introduction":{"en":"Choose an answer for each question and check the explanations. You can retry; these checks support learning and do not issue a provider certificate.","ar":"اختر إجابة لكل سؤال وراجع التفسير. يمكنك إعادة المحاولة؛ تدعم هذه الأسئلة التعلم ولا تمنح شهادة من الجهة الأصلية."},"sections":[],"questions":[{"question":{"en":"What does binary search require?","ar":"ماذا يتطلب البحث الثنائي؟"},"options":[{"en":"Sorted data","ar":"بيانات مرتبة"},{"en":"Randomly ordered data","ar":"بيانات عشوائية الترتيب"},{"en":"A network connection","ar":"اتصالاً بالشبكة"}],"answer":0,"explanation":{"en":"Ordering lets the algorithm discard half the remaining range.","ar":"يسمح الترتيب باستبعاد نصف المجال المتبقي."}},{"question":{"en":"What does Big-O describe?","ar":"ماذا تصف Big-O؟"},"options":[{"en":"Exact milliseconds on every computer","ar":"المللي ثانية بدقة على كل حاسوب"},{"en":"How work grows as input size grows","ar":"كيف ينمو العمل مع حجم المدخلات"},{"en":"The number of programming languages used","ar":"عدد لغات البرمجة المستخدمة"}],"answer":1,"explanation":{"en":"Hardware and implementation still affect actual runtime.","ar":"تؤثر الأجهزة وطريقة التنفيذ في الزمن الفعلي."}}]}'),
('javascript-foundations-watch', 'javascript-foundations', 0, 'video', '{"en":"Watch the complete source course","ar":"شاهد دورة المصدر كاملة"}', '{"introduction":{"en":"Play the complete publisher video here. Pause and resume with the player controls; lesson completion is marked manually after studying.","ar":"شغّل فيديو الناشر الكامل هنا. أوقف واستأنف من أدوات المشغل؛ توضع علامة إنجاز الدرس يدوياً بعد الدراسة."},"sections":[{"title":{"en":"Before watching","ar":"قبل المشاهدة"},"body":{"en":"A browser console or a recent Node.js installation. No framework knowledge is required.","ar":"وحدة تحكم المتصفح أو إصدار حديث من Node.js، دون الحاجة إلى معرفة إطار عمل."}},{"title":{"en":"Study actively","ar":"ادرس بتفاعل"},"body":{"en":"Work through examples in your own environment rather than only watching. Write down unfamiliar terms and record useful timestamps in your notes. Explain each major idea without looking at the recording, then use the next lessons to consolidate and practice it.","ar":"نفّذ الأمثلة في بيئتك بدلاً من المشاهدة وحدها. دوّن المصطلحات الجديدة والأوقات المفيدة في ملاحظاتك. اشرح الأفكار الأساسية دون الرجوع للتسجيل، ثم استخدم الدروس التالية لترسيخها وتطبيقها."}}]}'),
('javascript-foundations-concepts', 'javascript-foundations', 1, 'reading', '{"en":"Understand the core concepts","ar":"افهم المفاهيم الأساسية"}', '{"introduction":{"en":"A complete introduction to JavaScript with focused practice in functions, objects and transformations.","ar":"مقدمة كاملة لجافاسكربت مع تدريب على الدوال والكائنات وتحويل البيانات."},"sections":[{"title":{"en":"Scope, values and equality","ar":"النطاق والقيم والمساواة"},"body":{"en":"Use const when a binding will not be reassigned and let when it will. const does not make an object immutable. Prefer strict equality so comparison does not silently coerce types. An undefined property is different from a deliberate null value; decide how your functions handle each case.","ar":"استخدم const عندما لن يعاد إسناد الاسم وlet عند الحاجة لإسناده. لا تجعل const الكائن غير قابل للتغيير. فضّل المساواة الصارمة لتجنب تحويل الأنواع ضمنياً. تختلف الخاصية undefined عن القيمة null المقصودة؛ حدد كيف تتعامل الدالة مع كل حالة."}},{"title":{"en":"Functions and collection transformations","ar":"الدوال وتحويل المجموعات"},"body":{"en":"A function should state what it accepts and returns. Use map to transform entries and filter to retain entries satisfying a condition. Array methods that return a new array can make state changes easier to reason about. Avoid changing the original objects unexpectedly: copying an array does not deeply copy the objects inside it.","ar":"ينبغي أن يتضح ما تستقبله الدالة وما تعيده. استخدم map لتحويل العناصر وfilter للاحتفاظ بما يحقق شرطاً. تسهّل الطرق التي تعيد مصفوفة جديدة فهم تغير الحالة. تجنب تعديل الكائنات الأصلية على نحو غير متوقع؛ فنسخ المصفوفة لا ينسخ الكائنات داخلها بعمق."}},{"title":{"en":"Validate boundaries","ar":"تحقق من حدود البيانات"},"body":{"en":"Treat data from a form or network as untrusted input. Check expected types and ranges before using values in a calculation. Return a meaningful error rather than allowing NaN to spread through the result. Keep DOM rendering separate from the function that computes your result, so the computation can run in a browser or on a server.","ar":"تعامل مع بيانات النماذج والشبكة كمدخلات تحتاج إلى تحقق. افحص الأنواع والمدى قبل استخدامها في الحساب. أعد خطأ ذا معنى بدلاً من انتشار NaN في النتائج. افصل رسم DOM عن دالة الحساب كي تعمل في المتصفح أو الخادم."}}]}'),
('javascript-foundations-practice', 'javascript-foundations', 2, 'practice', '{"en":"Build a job shortlist","ar":"ابنِ قائمة وظائف مختارة"}', '{"introduction":{"en":"Turn the ideas into evidence of your understanding. Complete the exercise and keep a short explanation of your decisions.","ar":"حوّل الأفكار إلى دليل على فهمك. نفّذ التمرين واحتفظ بشرح موجز لقراراتك."},"sections":[{"title":{"en":"Build a job shortlist","ar":"ابنِ قائمة وظائف مختارة"},"body":{"en":"Create an array of job objects with title, location and requiredSkills. Write functions to filter by location, normalize skill names and return jobs matching at least two selected skills. Keep the original array unchanged.","ar":"أنشئ مصفوفة وظائف تضم المسمى والموقع والمهارات المطلوبة. اكتب دوال للتصفية بالموقع وتوحيد أسماء المهارات وإعادة الوظائف المطابقة لمهارتين مختارتين على الأقل. أبقِ المصفوفة الأصلية دون تغيير."}},{"title":{"en":"Check edge cases","ar":"افحص الحالات الحدية"},"body":{"en":"Test missing skills, mixed capitalization, an empty shortlist and repeated skills. Decide how to handle unknown locations. Write examples showing each transformation and explain where validation belongs if the same logic is later placed behind an API.","ar":"اختبر المهارات الناقصة واختلاف حالة الأحرف والقائمة الفارغة والمهارات المتكررة. حدد كيفية التعامل مع المواقع المجهولة. اكتب أمثلة لكل تحويل واشرح مكان التحقق إن نُقل المنطق إلى واجهة برمجية."}}]}'),
('javascript-foundations-check', 'javascript-foundations', 3, 'quiz', '{"en":"Check your understanding","ar":"اختبر فهمك"}', '{"introduction":{"en":"Choose an answer for each question and check the explanations. You can retry; these checks support learning and do not issue a provider certificate.","ar":"اختر إجابة لكل سؤال وراجع التفسير. يمكنك إعادة المحاولة؛ تدعم هذه الأسئلة التعلم ولا تمنح شهادة من الجهة الأصلية."},"sections":[],"questions":[{"question":{"en":"Does const prevent changing a property of an object?","ar":"هل تمنع const تغيير خاصية كائن؟"},"options":[{"en":"Yes, all properties become frozen","ar":"نعم، تتجمد جميع الخصائص"},{"en":"No, it prevents reassignment of the binding","ar":"لا، تمنع إعادة إسناد الاسم"},{"en":"Only inside an array","ar":"داخل المصفوفة فقط"}],"answer":1,"explanation":{"en":"Object immutability requires a separate design decision.","ar":"عدم قابلية الكائن للتغيير قرار تصميم منفصل."}},{"question":{"en":"Which method selects entries matching a condition?","ar":"أي طريقة تختار العناصر المطابقة لشرط؟"},"options":[{"en":"filter","ar":"filter"},{"en":"map","ar":"map"},{"en":"join","ar":"join"}],"answer":0,"explanation":{"en":"filter retains matching entries; map transforms entries.","ar":"تحتفظ filter بالعناصر المطابقة بينما تحول map العناصر."}}]}'),
('sql-data-watch', 'sql-data', 0, 'video', '{"en":"Watch the complete source course","ar":"شاهد دورة المصدر كاملة"}', '{"introduction":{"en":"Play the complete publisher video here. Pause and resume with the player controls; lesson completion is marked manually after studying.","ar":"شغّل فيديو الناشر الكامل هنا. أوقف واستأنف من أدوات المشغل؛ توضع علامة إنجاز الدرس يدوياً بعد الدراسة."},"sections":[{"title":{"en":"Before watching","ar":"قبل المشاهدة"},"body":{"en":"Basic data concepts. Use a local practice database with fictional records.","ar":"مفاهيم أولية عن البيانات. استخدم قاعدة تدريب محلية بسجلات افتراضية."}},{"title":{"en":"Study actively","ar":"ادرس بتفاعل"},"body":{"en":"Work through examples in your own environment rather than only watching. Write down unfamiliar terms and record useful timestamps in your notes. Explain each major idea without looking at the recording, then use the next lessons to consolidate and practice it.","ar":"نفّذ الأمثلة في بيئتك بدلاً من المشاهدة وحدها. دوّن المصطلحات الجديدة والأوقات المفيدة في ملاحظاتك. اشرح الأفكار الأساسية دون الرجوع للتسجيل، ثم استخدم الدروس التالية لترسيخها وتطبيقها."}}]}'),
('sql-data-concepts', 'sql-data', 1, 'reading', '{"en":"Understand the core concepts","ar":"افهم المفاهيم الأساسية"}', '{"introduction":{"en":"Learn the complete SQL video course and build a small, queryable recruitment dataset.","ar":"تعلّم من دورة SQL الكاملة وابنِ مجموعة بيانات توظيف صغيرة قابلة للاستعلام."},"sections":[{"title":{"en":"Model records and relationships","ar":"نمذجة السجلات والعلاقات"},"body":{"en":"A table models one kind of record. A primary key identifies a row; a foreign key connects related rows and can enforce referential integrity. Separate candidates, jobs and applications rather than repeating candidate details for every application. Decide which columns may be null and which values must be unique before importing records.","ar":"يمثل الجدول نوعاً واحداً من السجلات. يعرّف المفتاح الأساسي الصف، ويربط المفتاح الخارجي الصفوف ويمكنه فرض التكامل المرجعي. افصل المرشحين والوظائف والطلبات بدلاً من تكرار معلومات المرشح لكل طلب. حدد الأعمدة التي تسمح بالقيم الفارغة والقيم الفريدة قبل استيراد السجلات."}},{"title":{"en":"Query, join and aggregate","ar":"الاستعلام والربط والتجميع"},"body":{"en":"SELECT chooses columns and WHERE filters rows before grouping. JOIN combines records according to a condition; an inner join omits unmatched rows while a left join can preserve them. GROUP BY forms groups for aggregate calculations, and HAVING filters aggregated groups. A join can multiply rows, so count the right identifier rather than assuming one input row produces one output row.","ar":"تختار SELECT الأعمدة وترشح WHERE الصفوف قبل التجميع. يدمج JOIN السجلات وفق شرط؛ يستبعد الربط الداخلي غير المتطابق وقد يحافظ الربط الأيسر عليه. تكوّن GROUP BY مجموعات للحسابات التجميعية، وترشح HAVING المجموعات بعد التجميع. قد يضاعف الربط الصفوف؛ لذا احسب المعرّف الصحيح ولا تفترض تطابق عدد المدخلات والمخرجات."}},{"title":{"en":"Change data safely","ar":"تعديل البيانات بشكل موثوق"},"body":{"en":"Use transactions when several changes must succeed together. Parameterized queries keep values separate from SQL syntax. Indexes can speed selected reads but add write and storage costs; inspect the query plan instead of indexing every column. Explicitly define ordering when result order matters: a table has no guaranteed default order.","ar":"استخدم المعاملات عندما يجب أن تنجح عدة تعديلات معاً. تفصل الاستعلامات ذات المعاملات القيم عن صيغة SQL. قد تسرّع الفهارس قراءات محددة لكنها تزيد تكلفة الكتابة والتخزين؛ افحص خطة الاستعلام بدلاً من فهرسة كل عمود. عرّف الترتيب صراحة عند الحاجة إليه؛ فالجدول لا يملك ترتيباً افتراضياً مضموناً."}}]}'),
('sql-data-practice', 'sql-data', 2, 'practice', '{"en":"Create a recruitment dataset","ar":"أنشئ بيانات توظيف"}', '{"introduction":{"en":"Turn the ideas into evidence of your understanding. Complete the exercise and keep a short explanation of your decisions.","ar":"حوّل الأفكار إلى دليل على فهمك. نفّذ التمرين واحتفظ بشرح موجز لقراراتك."},"sections":[{"title":{"en":"Create a recruitment dataset","ar":"أنشئ بيانات توظيف"},"body":{"en":"Design candidates, jobs and applications tables with primary and foreign keys. Insert fictional records including a job with no applications. Write a query for applications per job, including jobs with zero applications, and a second query for candidates who applied to more than one job.","ar":"صمّم جداول المرشحين والوظائف والطلبات بمفاتيح أساسية وخارجية. أضف سجلات افتراضية تتضمن وظيفة بلا طلبات. اكتب استعلاماً لعدد الطلبات لكل وظيفة شاملاً الصفر، وآخر للمرشحين الذين تقدموا لأكثر من وظيفة."}},{"title":{"en":"Explain correctness","ar":"اشرح صحة النتائج"},"body":{"en":"Show the expected result for each query. Demonstrate how counting a nullable joined column differs from COUNT(*). Add a uniqueness rule preventing the same candidate from applying to the same job twice. Explain a transaction that creates an application and an associated audit record together.","ar":"اعرض النتيجة المتوقعة لكل استعلام. وضّح الفرق بين عد عمود قابل للفراغ بعد الربط وCOUNT(*). أضف قاعدة فريدة لمنع تكرار طلب المرشح للوظيفة نفسها. اشرح معاملة تنشئ الطلب وسجل تدقيقه معاً."}}]}'),
('sql-data-check', 'sql-data', 3, 'quiz', '{"en":"Check your understanding","ar":"اختبر فهمك"}', '{"introduction":{"en":"Choose an answer for each question and check the explanations. You can retry; these checks support learning and do not issue a provider certificate.","ar":"اختر إجابة لكل سؤال وراجع التفسير. يمكنك إعادة المحاولة؛ تدعم هذه الأسئلة التعلم ولا تمنح شهادة من الجهة الأصلية."},"sections":[],"questions":[{"question":{"en":"Which join can retain jobs with no applications?","ar":"أي ربط قد يحتفظ بوظائف بلا طلبات؟"},"options":[{"en":"INNER JOIN only","ar":"INNER JOIN فقط"},{"en":"LEFT JOIN from jobs","ar":"LEFT JOIN بدءاً من الوظائف"},{"en":"A join without a condition","ar":"ربط بلا شرط"}],"answer":1,"explanation":{"en":"The preserved left side includes unmatched jobs.","ar":"يتضمن الجانب الأيسر المحفوظ الوظائف غير المتطابقة."}},{"question":{"en":"Why parameterize a query?","ar":"لماذا نستخدم معاملات الاستعلام؟"},"options":[{"en":"To separate input values from SQL syntax","ar":"لفصل قيم المدخلات عن صيغة SQL"},{"en":"To automatically create an index","ar":"لإنشاء فهرس تلقائياً"},{"en":"To guarantee sorted results","ar":"لضمان ترتيب النتائج"}],"answer":0,"explanation":{"en":"Parameters prevent values from being interpreted as query syntax.","ar":"تمنع المعاملات تفسير القيم كجزء من صيغة الاستعلام."}}]}'),
('machine-learning-watch', 'machine-learning', 0, 'video', '{"en":"Watch the complete source course","ar":"شاهد دورة المصدر كاملة"}', '{"introduction":{"en":"Play the complete publisher video here. Pause and resume with the player controls; lesson completion is marked manually after studying.","ar":"شغّل فيديو الناشر الكامل هنا. أوقف واستأنف من أدوات المشغل؛ توضع علامة إنجاز الدرس يدوياً بعد الدراسة."},"sections":[{"title":{"en":"Before watching","ar":"قبل المشاهدة"},"body":{"en":"Basic Python, arithmetic and familiarity with tabular data.","ar":"أساسيات بايثون والحساب والتعامل مع البيانات الجدولية."}},{"title":{"en":"Study actively","ar":"ادرس بتفاعل"},"body":{"en":"Work through examples in your own environment rather than only watching. Write down unfamiliar terms and record useful timestamps in your notes. Explain each major idea without looking at the recording, then use the next lessons to consolidate and practice it.","ar":"نفّذ الأمثلة في بيئتك بدلاً من المشاهدة وحدها. دوّن المصطلحات الجديدة والأوقات المفيدة في ملاحظاتك. اشرح الأفكار الأساسية دون الرجوع للتسجيل، ثم استخدم الدروس التالية لترسيخها وتطبيقها."}}]}'),
('machine-learning-concepts', 'machine-learning', 1, 'reading', '{"en":"Understand the core concepts","ar":"افهم المفاهيم الأساسية"}', '{"introduction":{"en":"Study a complete introductory ML course, then practice splitting data and comparing a model with a baseline.","ar":"ادرس دورة كاملة في أساسيات تعلم الآلة ثم تدرب على تقسيم البيانات ومقارنة النموذج بخط أساس."},"sections":[{"title":{"en":"Frame a prediction problem","ar":"صياغة مشكلة التنبؤ"},"body":{"en":"Supervised learning uses examples with a target. Classification predicts a category while regression predicts a numeric value. Define what one row represents and when its features become available. A feature derived from the eventual outcome causes leakage if that information would not exist at prediction time.","ar":"يستخدم التعلم الخاضع للإشراف أمثلة لها هدف. يتنبأ التصنيف بفئة والانحدار بقيمة رقمية. حدد ما يمثله الصف ومتى تتاح خصائصه. تتسبب خاصية مشتقة من النتيجة النهائية بتسرب البيانات إذا لم تكن متاحة وقت التنبؤ."}},{"title":{"en":"Separate training from evaluation","ar":"فصل التدريب عن التقييم"},"body":{"en":"Training data fits model parameters; validation data helps select settings; a final test set estimates performance on unseen examples. Fit preprocessing only on training data, then apply the learned transformation to other splits. For time-dependent data, evaluate using a time-respecting split instead of shuffling information from the future into training.","ar":"تستخدم بيانات التدريب لضبط المعاملات، والتحقق لاختيار الإعدادات، والاختبار النهائي لتقدير الأداء على أمثلة جديدة. اضبط المعالجة المسبقة على بيانات التدريب فقط ثم طبّقها على البقية. في البيانات الزمنية استخدم تقسيماً يحترم الزمن بدلاً من خلط معلومات المستقبل ضمن التدريب."}},{"title":{"en":"Use metrics and baselines","ar":"استخدام المقاييس وخطوط الأساس"},"body":{"en":"Start with a simple baseline such as predicting the majority class. Accuracy can be misleading with rare positive cases. Precision describes how many predicted positives are correct; recall describes how many real positives are found. Choose metrics according to the cost of mistakes and inspect errors by meaningful groups before recommending deployment.","ar":"ابدأ بخط أساس بسيط مثل توقع الفئة الأكثر شيوعاً. قد تضلل الدقة العامة عندما تكون الحالات الإيجابية نادرة. تصف Precision نسبة الصحيح بين المتوقع إيجابياً، وRecall نسبة الإيجابيات الحقيقية التي عُثر عليها. اختر المقاييس وفق تكلفة الخطأ وافحص الأخطاء بحسب مجموعات ذات معنى قبل اقتراح النشر."}}]}'),
('machine-learning-practice', 'machine-learning', 2, 'practice', '{"en":"Build a reproducible baseline","ar":"ابنِ خط أساس قابلًا للتكرار"}', '{"introduction":{"en":"Turn the ideas into evidence of your understanding. Complete the exercise and keep a short explanation of your decisions.","ar":"حوّل الأفكار إلى دليل على فهمك. نفّذ التمرين واحتفظ بشرح موجز لقراراتك."},"sections":[{"title":{"en":"Build a reproducible baseline","ar":"ابنِ خط أساس قابلًا للتكرار"},"body":{"en":"Use a public practice dataset with a documented target. Create train, validation and test splits. Fit a baseline and one simple model using only training data. Record preprocessing steps, the split seed and the evaluation metric in a notebook.","ar":"استخدم بيانات تدريب عامة بهدف موثق. أنشئ تقسيمات التدريب والتحقق والاختبار. درّب خط أساس ونموذجاً بسيطاً على بيانات التدريب وحدها. وثق المعالجة المسبقة وبذرة التقسيم ومقياس التقييم في دفتر عمل."}},{"title":{"en":"Review errors, not only a score","ar":"راجع الأخطاء لا الدرجة وحدها"},"body":{"en":"Show a confusion matrix or a residual plot as appropriate. Describe at least three wrong predictions and possible data-quality issues. State what the metric does not establish and one condition under which the model should not be used.","ar":"اعرض مصفوفة التباس أو مخطط بواقي بحسب المهمة. صف ثلاثة توقعات خاطئة على الأقل ومشكلات محتملة في جودة البيانات. حدد ما لا يثبته المقياس وحالة واحدة لا ينبغي استخدام النموذج فيها."}}]}'),
('machine-learning-check', 'machine-learning', 3, 'quiz', '{"en":"Check your understanding","ar":"اختبر فهمك"}', '{"introduction":{"en":"Choose an answer for each question and check the explanations. You can retry; these checks support learning and do not issue a provider certificate.","ar":"اختر إجابة لكل سؤال وراجع التفسير. يمكنك إعادة المحاولة؛ تدعم هذه الأسئلة التعلم ولا تمنح شهادة من الجهة الأصلية."},"sections":[],"questions":[{"question":{"en":"Where should a scaler be fitted?","ar":"على أي بيانات يُضبط مقياس الخصائص؟"},"options":[{"en":"The entire dataset before splitting","ar":"كامل البيانات قبل التقسيم"},{"en":"Training data only","ar":"بيانات التدريب فقط"},{"en":"Only the final test set","ar":"مجموعة الاختبار النهائية فقط"}],"answer":1,"explanation":{"en":"Using test information to fit preprocessing leaks information into training.","ar":"يؤدي استخدام بيانات الاختبار لضبط المعالجة إلى تسرب المعلومات."}},{"question":{"en":"Which metric measures how many real positives are found?","ar":"أي مقياس يوضح نسبة الإيجابيات الحقيقية المكتشفة؟"},"options":[{"en":"Recall","ar":"Recall"},{"en":"Training loss alone","ar":"خسارة التدريب وحدها"},{"en":"Dataset size","ar":"حجم البيانات"}],"answer":0,"explanation":{"en":"Recall is true positives divided by all actual positives.","ar":"Recall هو الإيجابيات الصحيحة مقسوماً على كل الإيجابيات الفعلية."}}]}'),
('pytorch-deep-learning-watch', 'pytorch-deep-learning', 0, 'video', '{"en":"Watch the complete source course","ar":"شاهد دورة المصدر كاملة"}', '{"introduction":{"en":"Play the complete publisher video here. Pause and resume with the player controls; lesson completion is marked manually after studying.","ar":"شغّل فيديو الناشر الكامل هنا. أوقف واستأنف من أدوات المشغل؛ توضع علامة إنجاز الدرس يدوياً بعد الدراسة."},"sections":[{"title":{"en":"Before watching","ar":"قبل المشاهدة"},"body":{"en":"Python, tensors, basic ML evaluation and an environment with PyTorch installed. A GPU is optional for a small project.","ar":"بايثون والموترات وتقييم تعلم الآلة وبيئة تحتوي PyTorch. بطاقة رسومية اختيارية للمشروع الصغير."}},{"title":{"en":"Study actively","ar":"ادرس بتفاعل"},"body":{"en":"Work through examples in your own environment rather than only watching. Write down unfamiliar terms and record useful timestamps in your notes. Explain each major idea without looking at the recording, then use the next lessons to consolidate and practice it.","ar":"نفّذ الأمثلة في بيئتك بدلاً من المشاهدة وحدها. دوّن المصطلحات الجديدة والأوقات المفيدة في ملاحظاتك. اشرح الأفكار الأساسية دون الرجوع للتسجيل، ثم استخدم الدروس التالية لترسيخها وتطبيقها."}}]}'),
('pytorch-deep-learning-concepts', 'pytorch-deep-learning', 1, 'reading', '{"en":"Understand the core concepts","ar":"افهم المفاهيم الأساسية"}', '{"introduction":{"en":"A complete long-form PyTorch course with a study companion on training loops, evaluation and reproducible experiments.","ar":"دورة PyTorch كاملة وطويلة مع دليل لحلقات التدريب والتقييم والتجارب القابلة للتكرار."},"sections":[{"title":{"en":"Tensors, shapes and devices","ar":"الموترات والأبعاد والأجهزة"},"body":{"en":"A tensor has a shape, dtype and device. Write expected input and output shapes before implementing a layer. Broadcasting can make an incorrect operation run without raising an error, so assert important dimensions. Move the model and its inputs to the same device and avoid unnecessary transfers inside the training loop.","ar":"للموتر شكل ونوع بيانات وجهاز. اكتب أبعاد المدخلات والمخرجات قبل تنفيذ الطبقة. قد يسمح البث بتنفيذ عملية خاطئة دون خطأ برمجي؛ لذا تحقق من الأبعاد المهمة. ضع النموذج ومدخلاته على الجهاز نفسه وتجنب النقل غير الضروري داخل حلقة التدريب."}},{"title":{"en":"The training loop","ar":"حلقة التدريب"},"body":{"en":"A typical step clears accumulated gradients, computes predictions, evaluates loss, backpropagates and updates parameters. Gradients accumulate unless cleared intentionally. Loss describes the optimization objective, not necessarily the metric users care about. Keep a validation pass separate from parameter updates and monitor both training and validation curves.","ar":"تمسح الخطوة المعتادة التدرجات المتراكمة وتحسب التوقعات والخسارة ثم تنفذ الانتشار العكسي وتحدث المعاملات. تتراكم التدرجات ما لم تمسحها عمداً. تصف الخسارة هدف التحسين ولا تطابق دائماً مقياس المستخدم. افصل التحقق عن تحديث المعاملات وراقب منحنيي التدريب والتحقق."}},{"title":{"en":"Evaluation and experiment records","ar":"التقييم وتوثيق التجارب"},"body":{"en":"model.eval() changes behavior of layers such as dropout; it does not disable gradient recording. Use a no-gradient context for inference. Save architecture assumptions and preprocessing alongside weights. Record seeds and library versions, while recognizing that exact reproducibility can vary by hardware and operation.","ar":"تغيّر model.eval() سلوك طبقات مثل dropout لكنها لا توقف تسجيل التدرجات. استخدم سياقاً دون تدرجات للاستدلال. احفظ افتراضات المعمارية والمعالجة المسبقة مع الأوزان. وثّق البذور وإصدارات المكتبات مع مراعاة أن التطابق الكامل قد يختلف بحسب الأجهزة والعمليات."}}]}'),
('pytorch-deep-learning-practice', 'pytorch-deep-learning', 2, 'practice', '{"en":"Train a compact classifier","ar":"درّب مصنفاً صغيراً"}', '{"introduction":{"en":"Turn the ideas into evidence of your understanding. Complete the exercise and keep a short explanation of your decisions.","ar":"حوّل الأفكار إلى دليل على فهمك. نفّذ التمرين واحتفظ بشرح موجز لقراراتك."},"sections":[{"title":{"en":"Train a compact classifier","ar":"درّب مصنفاً صغيراً"},"body":{"en":"Choose a small public image dataset and document its license. Build a simple baseline and one compact neural network. Print the tensor shapes in a single diagnostic batch, then train with a separate validation set. Keep compute modest and save the best validation checkpoint.","ar":"اختر بيانات صور عامة صغيرة ووثّق ترخيصها. ابنِ خط أساس وشبكة عصبية صغيرة. اعرض أبعاد الموترات لدفعة تشخيص واحدة ثم درّب باستخدام مجموعة تحقق منفصلة. اجعل الحساب محدوداً واحفظ أفضل نقطة تحقق وفق التقييم."}},{"title":{"en":"Make inference repeatable","ar":"اجعل الاستدلال قابلاً للتكرار"},"body":{"en":"Load the saved weights into a fresh model instance. Run evaluation with the same preprocessing, model.eval() and no-gradient context. Compare one batch with the previous run and explain why comparing training-mode predictions could produce different outputs.","ar":"حمّل الأوزان المحفوظة في نسخة جديدة من النموذج. نفّذ التقييم بالمعالجة نفسها مع model.eval() وسياق دون تدرجات. قارن دفعة بالتشغيل السابق واشرح لماذا قد تختلف المخرجات عند المقارنة في وضع التدريب."}}]}'),
('pytorch-deep-learning-check', 'pytorch-deep-learning', 3, 'quiz', '{"en":"Check your understanding","ar":"اختبر فهمك"}', '{"introduction":{"en":"Choose an answer for each question and check the explanations. You can retry; these checks support learning and do not issue a provider certificate.","ar":"اختر إجابة لكل سؤال وراجع التفسير. يمكنك إعادة المحاولة؛ تدعم هذه الأسئلة التعلم ولا تمنح شهادة من الجهة الأصلية."},"sections":[],"questions":[{"question":{"en":"Does model.eval() disable gradient tracking?","ar":"هل توقف model.eval() تتبع التدرجات؟"},"options":[{"en":"Yes, always","ar":"نعم دائماً"},{"en":"No, use a no-gradient context as well","ar":"لا، استخدم أيضاً سياقاً دون تدرجات"},{"en":"Only on CPU","ar":"على المعالج فقط"}],"answer":1,"explanation":{"en":"Evaluation mode and gradient tracking are independent controls.","ar":"وضع التقييم وتتبع التدرجات آليتان مستقلتان."}},{"question":{"en":"Why clear gradients during ordinary training steps?","ar":"لماذا نمسح التدرجات في خطوات التدريب المعتادة؟"},"options":[{"en":"They accumulate by default","ar":"لأنها تتراكم افتراضياً"},{"en":"To delete the model weights","ar":"لحذف أوزان النموذج"},{"en":"To resize the training data","ar":"لتغيير حجم بيانات التدريب"}],"answer":0,"explanation":{"en":"Accumulation is useful when intentional, but otherwise changes the update.","ar":"يفيد التراكم عند قصده؛ وإلا فإنه يغير التحديث."}}]}'),
('google-cloud-watch', 'google-cloud', 0, 'video', '{"en":"Watch the complete source course","ar":"شاهد دورة المصدر كاملة"}', '{"introduction":{"en":"Play the complete publisher video here. Pause and resume with the player controls; lesson completion is marked manually after studying.","ar":"شغّل فيديو الناشر الكامل هنا. أوقف واستأنف من أدوات المشغل؛ توضع علامة إنجاز الدرس يدوياً بعد الدراسة."},"sections":[{"title":{"en":"Before watching","ar":"قبل المشاهدة"},"body":{"en":"Basic networking and command-line knowledge. Exercises can be completed as diagrams without a paid cloud account. The recording may use older console screens.","ar":"أساسيات الشبكات وسطر الأوامر. يمكن إتمام التمارين كمخططات دون حساب سحابي مدفوع. قد يعرض التسجيل واجهات تحكم أقدم."}},{"title":{"en":"Study actively","ar":"ادرس بتفاعل"},"body":{"en":"Work through examples in your own environment rather than only watching. Write down unfamiliar terms and record useful timestamps in your notes. Explain each major idea without looking at the recording, then use the next lessons to consolidate and practice it.","ar":"نفّذ الأمثلة في بيئتك بدلاً من المشاهدة وحدها. دوّن المصطلحات الجديدة والأوقات المفيدة في ملاحظاتك. اشرح الأفكار الأساسية دون الرجوع للتسجيل، ثم استخدم الدروس التالية لترسيخها وتطبيقها."}}]}'),
('google-cloud-concepts', 'google-cloud', 1, 'reading', '{"en":"Understand the core concepts","ar":"افهم المفاهيم الأساسية"}', '{"introduction":{"en":"Study cloud infrastructure through a complete Associate Cloud Engineer preparation video and a system-design exercise.","ar":"ادرس البنية السحابية عبر فيديو كامل للاستعداد لمهندس السحابة المساعد وتمرين لتصميم نظام."},"sections":[{"title":{"en":"Resource boundaries and identity","ar":"حدود الموارد والهوية"},"body":{"en":"Separate projects and environments so development changes do not affect production by accident. IAM answers who can perform which action on which resource. Grant only the permissions needed for a workload, prefer workload identities over long-lived credentials, and distinguish a human user from a service account. Network rules and identity permissions address different boundaries.","ar":"افصل المشاريع والبيئات كي لا تؤثر تعديلات التطوير في الإنتاج بالخطأ. تجيب IAM عن هوية من يستطيع تنفيذ إجراء على مورد. امنح الحمل الصلاحيات اللازمة فقط، وفضّل هوية حمل العمل على بيانات اعتماد طويلة العمر، وميّز المستخدم البشري عن حساب الخدمة. تعالج قواعد الشبكة وصلاحيات الهوية حدوداً مختلفة."}},{"title":{"en":"Choose services by workload","ar":"اختيار الخدمات بحسب الحمل"},"body":{"en":"A virtual machine gives operating-system control while a managed runtime removes some operational responsibilities. A managed database still requires decisions about schema, backups and access. Consider availability zones, failure recovery and data transfer costs when sketching architecture. A budget notification reports spending; it is not necessarily a hard spending cap.","ar":"تمنح الآلة الافتراضية تحكماً بنظام التشغيل بينما تقلل البيئة المدارة بعض المسؤوليات التشغيلية. تظل قاعدة البيانات المدارة بحاجة لقرارات حول المخطط والنسخ والوصول. راعِ نطاقات التوافر والتعافي وتكلفة نقل البيانات عند التصميم. يبلغ تنبيه الميزانية عن الإنفاق ولا يمثل بالضرورة حداً يوقفه."}}]}'),
('google-cloud-practice', 'google-cloud', 2, 'practice', '{"en":"Design a small learning platform","ar":"صمّم منصة تعلم صغيرة"}', '{"introduction":{"en":"Turn the ideas into evidence of your understanding. Complete the exercise and keep a short explanation of your decisions.","ar":"حوّل الأفكار إلى دليل على فهمك. نفّذ التمرين واحتفظ بشرح موجز لقراراتك."},"sections":[{"title":{"en":"Design a small learning platform","ar":"صمّم منصة تعلم صغيرة"},"body":{"en":"Draw a browser, application service, object store and managed database. Mark which connections are public and which require an authenticated workload. Choose a region and state what data needs a backup. No paid deployment is required.","ar":"ارسم متصفحاً وخدمة تطبيق ومخزن ملفات وقاعدة بيانات مدارة. حدد الاتصالات العامة والتي تتطلب هوية حمل عمل. اختر منطقة وحدد البيانات التي تحتاج إلى نسخة احتياطية. لا يلزم نشر مدفوع."}},{"title":{"en":"Write an operational review","ar":"اكتب مراجعة تشغيلية"},"body":{"en":"Describe what happens if the application process or one zone fails. Identify the least-privilege permissions for the app and list the main cost drivers. Explain how you would restore a backup and test it rather than assuming a backup guarantees recovery.","ar":"صف ما يحدث عند فشل عملية التطبيق أو نطاق توافر. حدد أقل صلاحيات يحتاجها التطبيق وأبرز عوامل التكلفة. اشرح استعادة النسخة الاحتياطية واختبارها بدلاً من افتراض أن وجودها يضمن التعافي."}}]}'),
('google-cloud-check', 'google-cloud', 3, 'quiz', '{"en":"Check your understanding","ar":"اختبر فهمك"}', '{"introduction":{"en":"Choose an answer for each question and check the explanations. You can retry; these checks support learning and do not issue a provider certificate.","ar":"اختر إجابة لكل سؤال وراجع التفسير. يمكنك إعادة المحاولة؛ تدعم هذه الأسئلة التعلم ولا تمنح شهادة من الجهة الأصلية."},"sections":[],"questions":[{"question":{"en":"What does IAM primarily control?","ar":"ما الذي تتحكم به IAM أساساً؟"},"options":[{"en":"Permissions on resources","ar":"الصلاحيات على الموارد"},{"en":"Only image resolution","ar":"دقة الصور فقط"},{"en":"The application programming language","ar":"لغة برمجة التطبيق"}],"answer":0,"explanation":{"en":"Identity and access management defines who can do what.","ar":"تحدد إدارة الهوية والوصول من يستطيع تنفيذ أي إجراء."}},{"question":{"en":"Does a budget alert always stop spending?","ar":"هل يوقف تنبيه الميزانية الإنفاق دائماً؟"},"options":[{"en":"Yes","ar":"نعم"},{"en":"No, alerts and hard enforcement are different","ar":"لا، يختلف التنبيه عن المنع الفعلي"},{"en":"Only when the browser is open","ar":"عند فتح المتصفح فقط"}],"answer":1,"explanation":{"en":"Check the provider controls instead of treating an alert as a cap.","ar":"تحقق من أدوات الجهة بدلاً من اعتبار التنبيه سقفاً ملزماً."}}]}'),
('docker-watch', 'docker', 0, 'video', '{"en":"Watch the complete source course","ar":"شاهد دورة المصدر كاملة"}', '{"introduction":{"en":"Play the complete publisher video here. Pause and resume with the player controls; lesson completion is marked manually after studying.","ar":"شغّل فيديو الناشر الكامل هنا. أوقف واستأنف من أدوات المشغل؛ توضع علامة إنجاز الدرس يدوياً بعد الدراسة."},"sections":[{"title":{"en":"Before watching","ar":"قبل المشاهدة"},"body":{"en":"Basic terminal commands and a small application. Docker is needed only for the practical exercise.","ar":"أوامر الطرفية الأساسية وتطبيق صغير. تحتاج Docker للتمرين العملي فقط."}},{"title":{"en":"Study actively","ar":"ادرس بتفاعل"},"body":{"en":"Work through examples in your own environment rather than only watching. Write down unfamiliar terms and record useful timestamps in your notes. Explain each major idea without looking at the recording, then use the next lessons to consolidate and practice it.","ar":"نفّذ الأمثلة في بيئتك بدلاً من المشاهدة وحدها. دوّن المصطلحات الجديدة والأوقات المفيدة في ملاحظاتك. اشرح الأفكار الأساسية دون الرجوع للتسجيل، ثم استخدم الدروس التالية لترسيخها وتطبيقها."}}]}'),
('docker-concepts', 'docker', 1, 'reading', '{"en":"Understand the core concepts","ar":"افهم المفاهيم الأساسية"}', '{"introduction":{"en":"A complete Docker introduction supported by a practical guide to images, containers and durable data.","ar":"مقدمة كاملة في Docker مع دليل عملي للصور والحاويات والبيانات الدائمة."},"sections":[{"title":{"en":"Images and running containers","ar":"الصور والحاويات المشغلة"},"body":{"en":"An image is a versioned package used to create containers. A container is a running instance with its own writable layer; changing that layer does not rebuild the image. A Dockerfile describes repeatable build steps. Copy dependency manifests before frequently changing source files to make useful build caching possible.","ar":"الصورة حزمة ذات إصدار تستخدم لإنشاء الحاويات. الحاوية نسخة مشغلة بطبقة كتابة خاصة؛ ولا يؤدي تعديلها إلى إعادة بناء الصورة. يصف Dockerfile خطوات بناء قابلة للتكرار. انسخ ملفات الاعتماديات قبل الملفات كثيرة التغيير للاستفادة من التخزين المؤقت للبناء."}},{"title":{"en":"Ports, volumes and configuration","ar":"المنافذ ووحدات التخزين والإعدادات"},"body":{"en":"A service listening inside a container is not automatically reachable on the host. Publish the required port intentionally. Use a volume for data that must outlive a container, and keep runtime configuration separate from the image. Do not bake credentials into an image: deleting a file in a later layer may not remove it from earlier layers.","ar":"لا تصبح الخدمة داخل الحاوية متاحة على المضيف تلقائياً؛ انشر المنفذ المطلوب عمداً. استخدم وحدة تخزين للبيانات التي يجب أن تبقى بعد الحاوية، وافصل إعدادات التشغيل عن الصورة. لا تضمّن بيانات الاعتماد في الصورة؛ فحذف ملف في طبقة لاحقة قد لا يزيله من الطبقات السابقة."}}]}'),
('docker-practice', 'docker', 2, 'practice', '{"en":"Containerize a small service","ar":"ضع خدمة صغيرة في حاوية"}', '{"introduction":{"en":"Turn the ideas into evidence of your understanding. Complete the exercise and keep a short explanation of your decisions.","ar":"حوّل الأفكار إلى دليل على فهمك. نفّذ التمرين واحتفظ بشرح موجز لقراراتك."},"sections":[{"title":{"en":"Containerize a small service","ar":"ضع خدمة صغيرة في حاوية"},"body":{"en":"Create a minimal HTTP service with a health endpoint. Write a Dockerfile using a specific base version, install dependencies and run as a non-root user where supported. Build the image locally and publish only the application port.","ar":"أنشئ خدمة HTTP صغيرة بنقطة فحص صحة. اكتب Dockerfile بإصدار أساس محدد وثبّت الاعتماديات وشغّل بمستخدم غير جذر متى أمكن. ابنِ الصورة محلياً وانشر منفذ التطبيق فقط."}},{"title":{"en":"Verify replacement behavior","ar":"تحقق من سلوك الاستبدال"},"body":{"en":"Stop and replace the container, then confirm what happens to files written inside it. Repeat using a volume for a sample data file. Document the build and run commands and explain why a successful image build alone does not prove the service is healthy.","ar":"أوقف الحاوية واستبدلها ثم تحقق مما يحدث للملفات المكتوبة داخلها. كرر باستخدام وحدة تخزين لملف بيانات تجريبي. وثّق أوامر البناء والتشغيل واشرح لماذا لا يثبت نجاح بناء الصورة سلامة الخدمة."}}]}'),
('docker-check', 'docker', 3, 'quiz', '{"en":"Check your understanding","ar":"اختبر فهمك"}', '{"introduction":{"en":"Choose an answer for each question and check the explanations. You can retry; these checks support learning and do not issue a provider certificate.","ar":"اختر إجابة لكل سؤال وراجع التفسير. يمكنك إعادة المحاولة؛ تدعم هذه الأسئلة التعلم ولا تمنح شهادة من الجهة الأصلية."},"sections":[],"questions":[{"question":{"en":"Which object is the running instance?","ar":"ما العنصر الذي يمثل النسخة المشغلة؟"},"options":[{"en":"A Dockerfile","ar":"Dockerfile"},{"en":"A container","ar":"الحاوية"},{"en":"An image tag","ar":"وسم الصورة"}],"answer":1,"explanation":{"en":"Containers are created from images.","ar":"تُنشأ الحاويات انطلاقاً من الصور."}},{"question":{"en":"Where should persistent application files live?","ar":"أين تحفظ ملفات التطبيق الدائمة؟"},"options":[{"en":"Only in the disposable container layer","ar":"في طبقة الحاوية المؤقتة فقط"},{"en":"In a deliberately configured persistent volume or service","ar":"في وحدة أو خدمة تخزين دائمة مضبوطة عمداً"},{"en":"In the image build log","ar":"في سجل بناء الصورة"}],"answer":1,"explanation":{"en":"Replacing a container should not erase durable application data.","ar":"يجب ألا يمحو استبدال الحاوية بيانات التطبيق الدائمة."}}]}'),
('kubernetes-watch', 'kubernetes', 0, 'video', '{"en":"Watch the complete source course","ar":"شاهد دورة المصدر كاملة"}', '{"introduction":{"en":"Play the complete publisher video here. Pause and resume with the player controls; lesson completion is marked manually after studying.","ar":"شغّل فيديو الناشر الكامل هنا. أوقف واستأنف من أدوات المشغل؛ توضع علامة إنجاز الدرس يدوياً بعد الدراسة."},"sections":[{"title":{"en":"Before watching","ar":"قبل المشاهدة"},"body":{"en":"Comfort with containers, networking and YAML. The video introduces Kubernetes; this pathway adds an advanced operations exercise.","ar":"إجادة الحاويات والشبكات وYAML. يقدّم الفيديو Kubernetes، ويضيف هذا المسار تمرين تشغيل متقدماً."}},{"title":{"en":"Study actively","ar":"ادرس بتفاعل"},"body":{"en":"Work through examples in your own environment rather than only watching. Write down unfamiliar terms and record useful timestamps in your notes. Explain each major idea without looking at the recording, then use the next lessons to consolidate and practice it.","ar":"نفّذ الأمثلة في بيئتك بدلاً من المشاهدة وحدها. دوّن المصطلحات الجديدة والأوقات المفيدة في ملاحظاتك. اشرح الأفكار الأساسية دون الرجوع للتسجيل، ثم استخدم الدروس التالية لترسيخها وتطبيقها."}}]}'),
('kubernetes-concepts', 'kubernetes', 1, 'reading', '{"en":"Understand the core concepts","ar":"افهم المفاهيم الأساسية"}', '{"introduction":{"en":"Study the complete Kubernetes video and design a resilient deployment with health checks and controlled rollouts.","ar":"ادرس فيديو Kubernetes الكامل وصمّم نشراً مرناً بفحوص صحة وتحديثات مدروسة."},"sections":[{"title":{"en":"Desired state and reconciliation","ar":"الحالة المطلوبة والمصالحة"},"body":{"en":"A Deployment declares the desired number and template of pods. Controllers repeatedly compare desired state with observed state and act to reduce the difference. Treat pods as replaceable rather than permanent hosts. A Service gives a stable discovery boundary while pod addresses may change.","ar":"يعلن Deployment العدد المطلوب وقالب وحدات pod. تقارن المتحكمات باستمرار الحالة المطلوبة بالمرصودة وتتخذ إجراءات لتقليص الفرق. تعامل مع pod كعنصر قابل للاستبدال لا كمضيف دائم. تتيح Service حد اكتشاف ثابتاً بينما قد تتغير عناوين الوحدات."}},{"title":{"en":"Health and controlled delivery","ar":"الصحة والتسليم المدروس"},"body":{"en":"Readiness determines whether a pod should receive traffic. Liveness decides when an unhealthy container should be restarted, while a startup probe can protect a slow startup from premature checks. Resource requests guide scheduling; limits bound some resource use. A rollout needs observable success criteria and a rollback plan, not only an updated image tag.","ar":"تحدد الجاهزية هل تستقبل الوحدة المرور. تحدد الحيوية متى تعاد الحاوية غير السليمة، وقد يحمي فحص بدء التشغيل الإقلاع البطيء من الفحوص المبكرة. توجه طلبات الموارد الجدولة وتحد الحدود بعض الاستخدام. يحتاج التحديث معايير نجاح قابلة للرصد وخطة تراجع، لا مجرد وسم صورة جديد."}}]}'),
('kubernetes-practice', 'kubernetes', 2, 'practice', '{"en":"Design a resilient deployment","ar":"صمّم نشراً مرناً"}', '{"introduction":{"en":"Turn the ideas into evidence of your understanding. Complete the exercise and keep a short explanation of your decisions.","ar":"حوّل الأفكار إلى دليل على فهمك. نفّذ التمرين واحتفظ بشرح موجز لقراراتك."},"sections":[{"title":{"en":"Design a resilient deployment","ar":"صمّم نشراً مرناً"},"body":{"en":"Write manifests for a small stateless application with two replicas and a Service. Define readiness and liveness endpoints, requests and limits. Use a local practice cluster if available, or review the manifests as a design exercise.","ar":"اكتب ملفات تعريف لتطبيق صغير عديم الحالة بنسختين وService. عرّف فحوص الجاهزية والحيوية وطلبات الموارد وحدودها. استخدم عنقود تدريب محلياً إن توفر أو راجع الملفات كتمرين تصميم."}},{"title":{"en":"Plan a failed rollout","ar":"خطط لتحديث يفشل"},"body":{"en":"Describe how a bad readiness check would affect traffic and what events or logs you would inspect. Specify the deployment conditions that trigger rollback. Explain why increasing replicas does not itself solve a broken application or guarantee multi-zone availability.","ar":"صف أثر فحص جاهزية خاطئ في المرور والأحداث والسجلات التي تفحصها. حدد شروط النشر التي تستدعي التراجع. اشرح لماذا لا تصلح زيادة النسخ تطبيقاً معطلاً ولا تضمن التوافر عبر نطاقات متعددة."}}]}'),
('kubernetes-check', 'kubernetes', 3, 'quiz', '{"en":"Check your understanding","ar":"اختبر فهمك"}', '{"introduction":{"en":"Choose an answer for each question and check the explanations. You can retry; these checks support learning and do not issue a provider certificate.","ar":"اختر إجابة لكل سؤال وراجع التفسير. يمكنك إعادة المحاولة؛ تدعم هذه الأسئلة التعلم ولا تمنح شهادة من الجهة الأصلية."},"sections":[],"questions":[{"question":{"en":"Which probe controls whether a pod receives traffic?","ar":"أي فحص يتحكم باستقبال pod للمرور؟"},"options":[{"en":"Readiness","ar":"الجاهزية"},{"en":"Image build","ar":"بناء الصورة"},{"en":"A source-code formatter","ar":"منسق الكود"}],"answer":0,"explanation":{"en":"A pod can be running while not ready to serve requests.","ar":"قد تكون الوحدة مشغلة لكنها غير جاهزة لتقديم الطلبات."}},{"question":{"en":"What does a controller reconcile?","ar":"ماذا يصالح المتحكم؟"},"options":[{"en":"Desired and observed state","ar":"الحالة المطلوبة والمرصودة"},{"en":"Only local editor settings","ar":"إعدادات المحرر المحلي فقط"},{"en":"Video playback speed","ar":"سرعة الفيديو"}],"answer":0,"explanation":{"en":"Reconciliation continually works toward the declared state.","ar":"تسعى المصالحة باستمرار لتحقيق الحالة المعلنة."}}]}'),
('linux-watch', 'linux', 0, 'video', '{"en":"Watch the complete source course","ar":"شاهد دورة المصدر كاملة"}', '{"introduction":{"en":"Play the complete publisher video here. Pause and resume with the player controls; lesson completion is marked manually after studying.","ar":"شغّل فيديو الناشر الكامل هنا. أوقف واستأنف من أدوات المشغل؛ توضع علامة إنجاز الدرس يدوياً بعد الدراسة."},"sections":[{"title":{"en":"Before watching","ar":"قبل المشاهدة"},"body":{"en":"A disposable local Linux environment or virtual machine for practice.","ar":"بيئة لينكس محلية قابلة للاستبدال أو آلة افتراضية للتدريب."}},{"title":{"en":"Study actively","ar":"ادرس بتفاعل"},"body":{"en":"Work through examples in your own environment rather than only watching. Write down unfamiliar terms and record useful timestamps in your notes. Explain each major idea without looking at the recording, then use the next lessons to consolidate and practice it.","ar":"نفّذ الأمثلة في بيئتك بدلاً من المشاهدة وحدها. دوّن المصطلحات الجديدة والأوقات المفيدة في ملاحظاتك. اشرح الأفكار الأساسية دون الرجوع للتسجيل، ثم استخدم الدروس التالية لترسيخها وتطبيقها."}}]}'),
('linux-concepts', 'linux', 1, 'reading', '{"en":"Understand the core concepts","ar":"افهم المفاهيم الأساسية"}', '{"introduction":{"en":"A full Linux course with a study guide to files, permissions, processes and system observation.","ar":"دورة لينكس كاملة مع دليل للملفات والصلاحيات والعمليات ومراقبة النظام."},"sections":[{"title":{"en":"Files, streams and composition","ar":"الملفات والتدفقات والتركيب"},"body":{"en":"An absolute path starts at the filesystem root; a relative path depends on the current directory. Standard input, output and error let small commands compose through pipes. Quote paths containing spaces and inspect a command before running it. Practice on copied sample files so mistakes do not affect personal data.","ar":"يبدأ المسار المطلق من جذر نظام الملفات ويعتمد النسبي على المجلد الحالي. تسمح تدفقات الإدخال والإخراج والخطأ بتركيب الأوامر عبر الأنابيب. ضع المسارات المحتوية على مسافات بين علامتي اقتباس وافهم الأمر قبل تشغيله. تدرب على نسخ ملفات تجريبية كي لا تؤثر الأخطاء في بياناتك."}},{"title":{"en":"Permissions and processes","ar":"الصلاحيات والعمليات"},"body":{"en":"File permissions distinguish owner, group and others, with read, write and execute flags. Execute permission on a directory has a different role from execute permission on a file. A process has a PID, an owner and resources. Diagnose with logs and process information before restarting or terminating a service; avoid using broad elevated privileges for routine work.","ar":"تميّز صلاحيات الملفات بين المالك والمجموعة والآخرين وأذونات القراءة والكتابة والتنفيذ. تختلف وظيفة إذن تنفيذ المجلد عن الملف. للعملية معرّف PID ومالك وموارد. شخّص بالسجلات ومعلومات العمليات قبل إعادة التشغيل أو الإنهاء، وتجنب الصلاحيات المرتفعة الواسعة في العمل المعتاد."}}]}'),
('linux-practice', 'linux', 2, 'practice', '{"en":"Inspect a practice system","ar":"افحص نظام تدريب"}', '{"introduction":{"en":"Turn the ideas into evidence of your understanding. Complete the exercise and keep a short explanation of your decisions.","ar":"حوّل الأفكار إلى دليل على فهمك. نفّذ التمرين واحتفظ بشرح موجز لقراراتك."},"sections":[{"title":{"en":"Inspect a practice system","ar":"افحص نظام تدريب"},"body":{"en":"Create a sample directory with a log file and a text report. Use commands to count lines, filter selected messages and write a summary to a new file. Change permissions only on the sample files and explain each flag.","ar":"أنشئ مجلد عينات بملف سجل وتقرير نصي. استخدم الأوامر لعد الأسطر وتصفية رسائل محددة وكتابة ملخص في ملف جديد. غيّر الصلاحيات على ملفات العينات فقط واشرح كل إذن."}},{"title":{"en":"Write a diagnostic runbook","ar":"اكتب دليل تشخيص"},"body":{"en":"List how to inspect disk usage, running processes and a service log without changing the system. Distinguish observation commands from destructive changes. Include the PID-based steps you would use to stop only a process you started.","ar":"اكتب كيفية فحص استخدام القرص والعمليات وسجل خدمة دون تعديل النظام. ميّز أوامر الرصد عن التغييرات الحذفية. أضف خطوات تستخدم PID لإيقاف العملية التي بدأتَها وحدها."}}]}'),
('linux-check', 'linux', 3, 'quiz', '{"en":"Check your understanding","ar":"اختبر فهمك"}', '{"introduction":{"en":"Choose an answer for each question and check the explanations. You can retry; these checks support learning and do not issue a provider certificate.","ar":"اختر إجابة لكل سؤال وراجع التفسير. يمكنك إعادة المحاولة؛ تدعم هذه الأسئلة التعلم ولا تمنح شهادة من الجهة الأصلية."},"sections":[],"questions":[{"question":{"en":"What identifies a running process?","ar":"ما الذي يعرّف عملية مشغلة؟"},"options":[{"en":"PID","ar":"PID"},{"en":"Only the filename extension","ar":"امتداد الملف فقط"},{"en":"A CSS class","ar":"فئة CSS"}],"answer":0,"explanation":{"en":"A PID can target a specific process.","ar":"يمكن استخدام PID لاستهداف عملية محددة."}},{"question":{"en":"Who is covered by the owner permission bits?","ar":"من تشمل أذونات المالك؟"},"options":[{"en":"Every visitor to a website","ar":"كل زائر لموقع"},{"en":"The file owner","ar":"مالك الملف"},{"en":"Only the browser","ar":"المتصفح فقط"}],"answer":1,"explanation":{"en":"Owner, group and others have separate permission sets.","ar":"للمالك والمجموعة والآخرين مجموعات أذونات منفصلة."}}]}'),
('security-labs-watch', 'security-labs', 0, 'video', '{"en":"Watch the complete source course","ar":"شاهد دورة المصدر كاملة"}', '{"introduction":{"en":"Play the complete publisher video here. Pause and resume with the player controls; lesson completion is marked manually after studying.","ar":"شغّل فيديو الناشر الكامل هنا. أوقف واستأنف من أدوات المشغل؛ توضع علامة إنجاز الدرس يدوياً بعد الدراسة."},"sections":[{"title":{"en":"Before watching","ar":"قبل المشاهدة"},"body":{"en":"Linux and networking fundamentals. Practical activity is limited to systems you own or have explicit permission to test.","ar":"أساسيات لينكس والشبكات. يقتصر التطبيق على أنظمة تملكها أو لديك إذن صريح لاختبارها."}},{"title":{"en":"Study actively","ar":"ادرس بتفاعل"},"body":{"en":"Work through examples in your own environment rather than only watching. Write down unfamiliar terms and record useful timestamps in your notes. Explain each major idea without looking at the recording, then use the next lessons to consolidate and practice it.","ar":"نفّذ الأمثلة في بيئتك بدلاً من المشاهدة وحدها. دوّن المصطلحات الجديدة والأوقات المفيدة في ملاحظاتك. اشرح الأفكار الأساسية دون الرجوع للتسجيل، ثم استخدم الدروس التالية لترسيخها وتطبيقها."}}]}'),
('security-labs-concepts', 'security-labs', 1, 'reading', '{"en":"Understand the core concepts","ar":"افهم المفاهيم الأساسية"}', '{"introduction":{"en":"A complete ethical-hacking video paired with a defensive study guide and an isolated lab-report exercise.","ar":"فيديو كامل للاختبار الأخلاقي مع دليل دفاعي وتمرين تقرير مختبر معزول."},"sections":[{"title":{"en":"Scope and evidence","ar":"النطاق والأدلة"},"body":{"en":"Define the systems, time window and allowed actions before a security assessment. Good evidence records what was observed and how to reproduce it in the authorized environment. Separate an observation from an inference. An open port is not automatically a vulnerability; exposure, software behavior and compensating controls matter.","ar":"حدد الأنظمة والفترة الزمنية والإجراءات المسموحة قبل التقييم الأمني. تسجل الأدلة الجيدة ما لوحظ وكيف يعاد إنتاجه في البيئة المصرح بها. افصل الملاحظة عن الاستنتاج. لا يمثل المنفذ المفتوح ثغرة تلقائياً؛ فالتعرض وسلوك البرنامج والضوابط التعويضية عوامل مهمة."}},{"title":{"en":"Risk and remediation","ar":"المخاطر والمعالجة"},"body":{"en":"A useful finding connects a weakness to a realistic impact and a specific remediation. Prioritize by exposure and consequence, not only an automated score. Keep credentials and personal data out of reports. Recommend verification steps so a team can confirm the fix without repeating an unnecessary intrusive test.","ar":"يربط الاكتشاف المفيد نقطة الضعف بأثر واقعي ومعالجة محددة. رتّب الأولوية وفق التعرض والعواقب لا درجة آلية وحدها. أبقِ بيانات الاعتماد والبيانات الشخصية خارج التقارير. اقترح خطوات تحقق تمكّن الفريق من تأكيد الإصلاح دون تكرار اختبار تدخلي غير لازم."}}]}'),
('security-labs-practice', 'security-labs', 2, 'practice', '{"en":"Create an authorized lab plan","ar":"أنشئ خطة مختبر مصرح"}', '{"introduction":{"en":"Turn the ideas into evidence of your understanding. Complete the exercise and keep a short explanation of your decisions.","ar":"حوّل الأفكار إلى دليل على فهمك. نفّذ التمرين واحتفظ بشرح موجز لقراراتك."},"sections":[{"title":{"en":"Create an authorized lab plan","ar":"أنشئ خطة مختبر مصرح"},"body":{"en":"Draw a local training network containing fictional services. Write scope, allowed observation tasks, stop conditions and evidence-handling rules. Do not test public systems. Identify one hypothetical misconfiguration and describe how a defender could detect and correct it.","ar":"ارسم شبكة تدريب محلية بخدمات افتراضية. اكتب النطاق ومهام الرصد المسموحة وشروط التوقف وقواعد التعامل مع الأدلة. لا تختبر أنظمة عامة. حدد خطأ إعداد افتراضياً وصف كيفية كشفه وتصحيحه دفاعياً."}},{"title":{"en":"Write a finding and retest","ar":"اكتب اكتشافاً وخطة إعادة تحقق"},"body":{"en":"Prepare a finding with summary, evidence, impact, affected lab component and remediation. Remove any sensitive sample values. Add a retest checklist that checks the configuration change and expected normal operation.","ar":"أعد اكتشافاً يتضمن ملخصاً وأدلة وأثراً ومكون المختبر المتأثر والمعالجة. أزل القيم الحساسة من العينات. أضف قائمة إعادة تحقق تفحص تعديل الإعداد واستمرار التشغيل الطبيعي المتوقع."}}]}'),
('security-labs-check', 'security-labs', 3, 'quiz', '{"en":"Check your understanding","ar":"اختبر فهمك"}', '{"introduction":{"en":"Choose an answer for each question and check the explanations. You can retry; these checks support learning and do not issue a provider certificate.","ar":"اختر إجابة لكل سؤال وراجع التفسير. يمكنك إعادة المحاولة؛ تدعم هذه الأسئلة التعلم ولا تمنح شهادة من الجهة الأصلية."},"sections":[],"questions":[{"question":{"en":"When may you assess a system?","ar":"متى يجوز تقييم نظام؟"},"options":[{"en":"Whenever its address is public","ar":"بمجرد كون عنوانه عاماً"},{"en":"Within explicit authorization and agreed scope","ar":"ضمن إذن صريح ونطاق متفق عليه"},{"en":"Only if a tool finds it automatically","ar":"إذا عثرت عليه أداة تلقائياً فقط"}],"answer":1,"explanation":{"en":"Technical reachability does not establish authorization.","ar":"لا تعني إمكانية الوصول التقني وجود إذن."}},{"question":{"en":"What makes a finding actionable?","ar":"ما الذي يجعل الاكتشاف قابلاً للمعالجة؟"},"options":[{"en":"A dramatic title without evidence","ar":"عنوان مثير بلا أدلة"},{"en":"Evidence, impact and a specific remediation","ar":"أدلة وأثر ومعالجة محددة"},{"en":"A screenshot alone","ar":"لقطة شاشة وحدها"}],"answer":1,"explanation":{"en":"The team needs enough context to prioritize and verify a fix.","ar":"يحتاج الفريق سياقاً كافياً لترتيب الأولوية والتحقق من الإصلاح."}}]}'),
('figma-design-watch', 'figma-design', 0, 'video', '{"en":"Watch the complete source course","ar":"شاهد دورة المصدر كاملة"}', '{"introduction":{"en":"Play the complete publisher video here. Pause and resume with the player controls; lesson completion is marked manually after studying.","ar":"شغّل فيديو الناشر الكامل هنا. أوقف واستأنف من أدوات المشغل؛ توضع علامة إنجاز الدرس يدوياً بعد الدراسة."},"sections":[{"title":{"en":"Before watching","ar":"قبل المشاهدة"},"body":{"en":"A Figma account is useful for the exercise; paper sketches work for the first stage.","ar":"يفيد حساب Figma للتطبيق؛ وتكفي الرسوم الورقية للمرحلة الأولى."}},{"title":{"en":"Study actively","ar":"ادرس بتفاعل"},"body":{"en":"Work through examples in your own environment rather than only watching. Write down unfamiliar terms and record useful timestamps in your notes. Explain each major idea without looking at the recording, then use the next lessons to consolidate and practice it.","ar":"نفّذ الأمثلة في بيئتك بدلاً من المشاهدة وحدها. دوّن المصطلحات الجديدة والأوقات المفيدة في ملاحظاتك. اشرح الأفكار الأساسية دون الرجوع للتسجيل، ثم استخدم الدروس التالية لترسيخها وتطبيقها."}}]}'),
('figma-design-concepts', 'figma-design', 1, 'reading', '{"en":"Understand the core concepts","ar":"افهم المفاهيم الأساسية"}', '{"introduction":{"en":"A complete Figma design tutorial with an original workflow for research, interaction and accessible prototypes.","ar":"شرح تصميم كامل باستخدام Figma مع منهج للبحث والتفاعل والنماذج القابلة للوصول."},"sections":[{"title":{"en":"Start with the user task","ar":"ابدأ بمهمة المستخدم"},"body":{"en":"A wireframe communicates structure before visual polish. Define the user, goal and context, then map the shortest clear path to completing the task. Separate a research observation from your assumption. Include empty, loading and error states in the flow instead of designing only a populated success screen.","ar":"يوضح المخطط الهيكل قبل التجميل البصري. حدد المستخدم والهدف والسياق ثم ارسم أقصر مسار واضح لإنجاز المهمة. افصل ملاحظة البحث عن افتراضك. ضمّن حالات الفراغ والتحميل والخطأ بدلاً من تصميم شاشة نجاح ممتلئة وحدها."}},{"title":{"en":"Components and accessible interaction","ar":"المكونات والتفاعل القابل للوصول"},"body":{"en":"Reusable components keep labels, spacing and behavior consistent. Design focus and selected states, not only hover. Use readable contrast and meaningful text labels rather than color alone to communicate status. A clickable prototype tests whether people understand the flow; it does not prove the implementation is accessible without testing the real interface.","ar":"تحافظ المكونات القابلة لإعادة الاستخدام على اتساق التسميات والمسافات والسلوك. صمّم حالتي التركيز والتحديد لا التحويم وحده. استخدم تبايناً مقروءاً وتسميات ذات معنى بدلاً من اللون وحده للحالة. يختبر النموذج القابل للنقر فهم المسار، لكنه لا يثبت قابلية التطبيق للوصول دون اختبار الواجهة الحقيقية."}}]}'),
('figma-design-practice', 'figma-design', 2, 'practice', '{"en":"Design a course enrollment flow","ar":"صمّم مسار الالتحاق بدورة"}', '{"introduction":{"en":"Turn the ideas into evidence of your understanding. Complete the exercise and keep a short explanation of your decisions.","ar":"حوّل الأفكار إلى دليل على فهمك. نفّذ التمرين واحتفظ بشرح موجز لقراراتك."},"sections":[{"title":{"en":"Design a course enrollment flow","ar":"صمّم مسار الالتحاق بدورة"},"body":{"en":"Sketch a course list, course overview and lesson view. Define what the learner needs at each step. Create low-fidelity wireframes, then a reusable button and course-card component. Include a no-results state and a failed-loading state.","ar":"ارسم قائمة دورات ونظرة عامة وصفحة درس. حدد حاجة المتعلم في كل خطوة. أنشئ مخططات أولية ثم مكون زر وبطاقة دورة قابلين لإعادة الاستخدام. ضمّن حالة بلا نتائج وأخرى لفشل التحميل."}},{"title":{"en":"Test comprehension","ar":"اختبر الفهم"},"body":{"en":"Ask a willing participant to find a beginner course and open its first lesson using the prototype. Record where they hesitate without leading them. Revise one confusing interaction and document the evidence behind the change.","ar":"اطلب من مشارك راغب العثور على دورة مبتدئة وفتح أول درس في النموذج. سجل مواضع التردد دون توجيه الإجابات. عدّل تفاعلاً مربكاً ووثّق الأدلة وراء التغيير."}}]}'),
('figma-design-check', 'figma-design', 3, 'quiz', '{"en":"Check your understanding","ar":"اختبر فهمك"}', '{"introduction":{"en":"Choose an answer for each question and check the explanations. You can retry; these checks support learning and do not issue a provider certificate.","ar":"اختر إجابة لكل سؤال وراجع التفسير. يمكنك إعادة المحاولة؛ تدعم هذه الأسئلة التعلم ولا تمنح شهادة من الجهة الأصلية."},"sections":[],"questions":[{"question":{"en":"What is the main purpose of an early wireframe?","ar":"ما الهدف الأساسي من المخطط الأولي؟"},"options":[{"en":"Communicate structure and flow","ar":"توضيح الهيكل والمسار"},{"en":"Prove production performance","ar":"إثبات أداء الإنتاج"},{"en":"Replace all user research","ar":"استبدال أبحاث المستخدمين"}],"answer":0,"explanation":{"en":"Low-fidelity structure makes early changes less costly.","ar":"يجعل الهيكل الأولي التغييرات المبكرة أقل تكلفة."}},{"question":{"en":"Should color alone communicate an error?","ar":"هل يكفي اللون وحده لتوضيح الخطأ؟"},"options":[{"en":"Yes","ar":"نعم"},{"en":"No, include a meaningful label or other cue","ar":"لا، أضف تسمية أو إشارة ذات معنى"},{"en":"Only on small screens","ar":"على الشاشات الصغيرة فقط"}],"answer":1,"explanation":{"en":"Text and other cues make status understandable beyond color perception.","ar":"تجعل النصوص والإشارات الأخرى الحالة مفهومة دون الاعتماد على إدراك اللون."}}]}'),
('kotlin-mobile-watch', 'kotlin-mobile', 0, 'video', '{"en":"Watch the complete source course","ar":"شاهد دورة المصدر كاملة"}', '{"introduction":{"en":"Play the complete publisher video here. Pause and resume with the player controls; lesson completion is marked manually after studying.","ar":"شغّل فيديو الناشر الكامل هنا. أوقف واستأنف من أدوات المشغل؛ توضع علامة إنجاز الدرس يدوياً بعد الدراسة."},"sections":[{"title":{"en":"Before watching","ar":"قبل المشاهدة"},"body":{"en":"A Kotlin playground or local Kotlin environment. This is a language foundation, not a complete Android app-development certification.","ar":"بيئة Kotlin محلية أو ساحة تجريب. هذه أساسيات اللغة وليست شهادة متكاملة لتطوير أندرويد."}},{"title":{"en":"Study actively","ar":"ادرس بتفاعل"},"body":{"en":"Work through examples in your own environment rather than only watching. Write down unfamiliar terms and record useful timestamps in your notes. Explain each major idea without looking at the recording, then use the next lessons to consolidate and practice it.","ar":"نفّذ الأمثلة في بيئتك بدلاً من المشاهدة وحدها. دوّن المصطلحات الجديدة والأوقات المفيدة في ملاحظاتك. اشرح الأفكار الأساسية دون الرجوع للتسجيل، ثم استخدم الدروس التالية لترسيخها وتطبيقها."}}]}'),
('kotlin-mobile-concepts', 'kotlin-mobile', 1, 'reading', '{"en":"Understand the core concepts","ar":"افهم المفاهيم الأساسية"}', '{"introduction":{"en":"A complete Kotlin programming course with exercises on null safety, data models and state transitions.","ar":"دورة Kotlin كاملة مع تمارين على أمان القيم الفارغة ونماذج البيانات وانتقالات الحالة."},"sections":[{"title":{"en":"Nullability and explicit models","ar":"القيم الفارغة والنماذج الصريحة"},"body":{"en":"Kotlin distinguishes nullable and non-null types. A safe call handles a nullable receiver without forcing a crash; a non-null assertion should not replace reasoning about missing values. Data classes describe value-like records. Model the states your application can actually enter rather than combining several booleans that allow impossible combinations.","ar":"تميّز Kotlin بين الأنواع القابلة للفراغ وغيرها. يعالج الاستدعاء الآمن قيمة قابلة للفراغ دون فرض انهيار؛ ولا ينبغي أن يحل تأكيد عدم الفراغ محل فهم البيانات الناقصة. تصف data class سجلات القيم. مثّل حالات التطبيق الفعلية بدلاً من جمع متغيرات منطقية تسمح بتراكيب مستحيلة."}},{"title":{"en":"Functions and immutable transformations","ar":"الدوال والتحويلات دون تعديل الأصل"},"body":{"en":"Use val for bindings that are not reassigned, while remembering that the referenced object may still be mutable. Express transformations with functions that receive values and return new values. Keep network or UI side effects outside core calculation logic. This separation helps a mobile app survive lifecycle changes without losing track of state ownership.","ar":"استخدم val للأسماء التي لا يعاد إسنادها مع تذكر أن الكائن المشار إليه قد يبقى قابلاً للتعديل. عبّر عن التحويلات بدوال تستقبل قيماً وتعيد قيماً جديدة. افصل آثار الشبكة والواجهة عن الحساب الأساسي. يساعد الفصل تطبيق الجوال على التعامل مع دورة الحياة وفهم ملكية الحالة."}}]}'),
('kotlin-mobile-practice', 'kotlin-mobile', 2, 'practice', '{"en":"Model a learning screen","ar":"نمذج شاشة تعلم"}', '{"introduction":{"en":"Turn the ideas into evidence of your understanding. Complete the exercise and keep a short explanation of your decisions.","ar":"حوّل الأفكار إلى دليل على فهمك. نفّذ التمرين واحتفظ بشرح موجز لقراراتك."},"sections":[{"title":{"en":"Model a learning screen","ar":"نمذج شاشة تعلم"},"body":{"en":"Create Kotlin data types for a course and lesson. Represent screen states such as loading, loaded and failed using explicit types. Write a function that marks a lesson complete and returns an updated model without changing the original input.","ar":"أنشئ أنواع بيانات Kotlin للدورة والدرس. مثّل حالات الشاشة كالتحميل والنجاح والفشل بأنواع صريحة. اكتب دالة تضع علامة إنجاز على درس وتعيد نموذجاً محدّثاً دون تغيير المدخل الأصلي."}},{"title":{"en":"Exercise state boundaries","ar":"اختبر حدود الحالة"},"body":{"en":"Test an empty course, an unknown lesson ID and marking the same lesson twice. Decide how progress is calculated when there are no lessons. Explain which layer should save progress and which layer should only display it.","ar":"اختبر دورة فارغة ومعرّف درس مجهولاً وتعليم الدرس نفسه مرتين. حدد حساب التقدم عند غياب الدروس. اشرح الطبقة التي تحفظ التقدم وتلك التي تعرضه فقط."}}]}'),
('kotlin-mobile-check', 'kotlin-mobile', 3, 'quiz', '{"en":"Check your understanding","ar":"اختبر فهمك"}', '{"introduction":{"en":"Choose an answer for each question and check the explanations. You can retry; these checks support learning and do not issue a provider certificate.","ar":"اختر إجابة لكل سؤال وراجع التفسير. يمكنك إعادة المحاولة؛ تدعم هذه الأسئلة التعلم ولا تمنح شهادة من الجهة الأصلية."},"sections":[],"questions":[{"question":{"en":"What does a nullable type express?","ar":"عمّ يعبّر النوع القابل للفراغ؟"},"options":[{"en":"A value may be absent","ar":"قد تكون القيمة غائبة"},{"en":"The value is always a string","ar":"القيمة نص دائماً"},{"en":"The application is offline","ar":"التطبيق غير متصل"}],"answer":0,"explanation":{"en":"Nullability makes missing data explicit in the type.","ar":"يجعل النوع احتمال غياب البيانات صريحاً."}},{"question":{"en":"Does val guarantee a deeply immutable object?","ar":"هل تضمن val كائناً غير قابل للتعديل بعمق؟"},"options":[{"en":"Yes","ar":"نعم"},{"en":"No, it prevents reassignment of the binding","ar":"لا، تمنع إعادة إسناد الاسم"},{"en":"Only for network requests","ar":"لطلبات الشبكة فقط"}],"answer":1,"explanation":{"en":"The referenced collection or object can still be mutable.","ar":"قد يبقى الكائن أو المجموعة المشار إليها قابلاً للتعديل."}}]}'),
('blockchain-engineering-watch', 'blockchain-engineering', 0, 'video', '{"en":"Watch the complete source course","ar":"شاهد دورة المصدر كاملة"}', '{"introduction":{"en":"Play the complete publisher video here. Pause and resume with the player controls; lesson completion is marked manually after studying.","ar":"شغّل فيديو الناشر الكامل هنا. أوقف واستأنف من أدوات المشغل؛ توضع علامة إنجاز الدرس يدوياً بعد الدراسة."},"sections":[{"title":{"en":"Before watching","ar":"قبل المشاهدة"},"body":{"en":"JavaScript and software testing fundamentals. Use a local development network and test accounts only; tooling in the recording may differ from current versions.","ar":"أساسيات جافاسكربت واختبار البرمجيات. استخدم شبكة تطوير محلية وحسابات اختبار فقط؛ قد تختلف أدوات التسجيل عن الإصدارات الحالية."}},{"title":{"en":"Study actively","ar":"ادرس بتفاعل"},"body":{"en":"Work through examples in your own environment rather than only watching. Write down unfamiliar terms and record useful timestamps in your notes. Explain each major idea without looking at the recording, then use the next lessons to consolidate and practice it.","ar":"نفّذ الأمثلة في بيئتك بدلاً من المشاهدة وحدها. دوّن المصطلحات الجديدة والأوقات المفيدة في ملاحظاتك. اشرح الأفكار الأساسية دون الرجوع للتسجيل، ثم استخدم الدروس التالية لترسيخها وتطبيقها."}}]}'),
('blockchain-engineering-concepts', 'blockchain-engineering', 1, 'reading', '{"en":"Understand the core concepts","ar":"افهم المفاهيم الأساسية"}', '{"introduction":{"en":"A complete 32-hour publisher course with a companion on contract state, transactions and testing.","ar":"دورة كاملة مدتها 32 ساعة من الناشر مع دليل لحالة العقود والمعاملات والاختبار."},"sections":[{"title":{"en":"State, transactions and trust","ar":"الحالة والمعاملات والثقة"},"body":{"en":"A contract defines state and the rules for changing it. A read call and a state-changing transaction have different execution and confirmation behavior. Transactions can fail and state changes must satisfy the contract rules. A network transaction identifier is not proof that an application-level goal was achieved; inspect the outcome and emitted events.","ar":"يعرّف العقد الحالة وقواعد تغييرها. يختلف تنفيذ استدعاء القراءة وتأكيده عن معاملة تغيّر الحالة. قد تفشل المعاملة ويجب أن تحقق التغييرات قواعد العقد. لا يثبت معرّف المعاملة وحده نجاح هدف التطبيق؛ افحص النتيجة والأحداث المصدرة."}},{"title":{"en":"Test invariants and access boundaries","ar":"اختبار الثوابت وحدود الوصول"},"body":{"en":"Specify properties that must hold across every valid sequence of calls. Check who may change sensitive state and how unexpected input is rejected. External calls create control-flow risk, so think carefully about updating state and interacting with other contracts. A local test suite is useful evidence, but it is not a substitute for an independent security review before handling real assets.","ar":"حدد الخصائص التي يجب أن تصح عبر كل تسلسل استدعاءات صالح. تحقق ممن يغيّر الحالة الحساسة وكيف ترفض المدخلات غير المتوقعة. تنشئ الاستدعاءات الخارجية مخاطر في تدفق التحكم؛ فكر في ترتيب تحديث الحالة والتفاعل مع العقود. الاختبارات المحلية دليل مفيد لكنها لا تستبدل مراجعة أمنية مستقلة قبل التعامل مع أصول حقيقية."}}]}'),
('blockchain-engineering-practice', 'blockchain-engineering', 2, 'practice', '{"en":"Build a local completion registry","ar":"ابنِ سجل إنجاز محلياً"}', '{"introduction":{"en":"Turn the ideas into evidence of your understanding. Complete the exercise and keep a short explanation of your decisions.","ar":"حوّل الأفكار إلى دليل على فهمك. نفّذ التمرين واحتفظ بشرح موجز لقراراتك."},"sections":[{"title":{"en":"Build a local completion registry","ar":"ابنِ سجل إنجاز محلياً"},"body":{"en":"On a local development chain, design a registry where an authorized issuer records completion for a learner address and course ID. Reject unauthorized writes and duplicate entries. Emit an event and create tests for success and failure paths. Do not put personal learner data on a public chain.","ar":"على سلسلة تطوير محلية، صمّم سجلاً تسجل فيه جهة مخولة إنجاز عنوان متعلم لدورة. ارفض الكتابات غير المخولة والسجلات المتكررة. أصدر حدثاً واكتب اختبارات النجاح والفشل. لا تضع بيانات شخصية للمتعلمين على سلسلة عامة."}},{"title":{"en":"Explain the trust model","ar":"اشرح نموذج الثقة"},"body":{"en":"Describe what a registry entry proves and what it does not prove about skill or identity. Explain key loss, issuer revocation and contract upgrade decisions. Document dependencies and test-network setup without including account credentials.","ar":"صف ما يثبته سجل الإنجاز وما لا يثبته عن المهارة أو الهوية. اشرح فقدان المفاتيح وإلغاء صلاحية الجهة وقرارات ترقية العقد. وثّق الاعتماديات وإعداد شبكة الاختبار دون بيانات اعتماد الحساب."}}]}'),
('blockchain-engineering-check', 'blockchain-engineering', 3, 'quiz', '{"en":"Check your understanding","ar":"اختبر فهمك"}', '{"introduction":{"en":"Choose an answer for each question and check the explanations. You can retry; these checks support learning and do not issue a provider certificate.","ar":"اختر إجابة لكل سؤال وراجع التفسير. يمكنك إعادة المحاولة؛ تدعم هذه الأسئلة التعلم ولا تمنح شهادة من الجهة الأصلية."},"sections":[],"questions":[{"question":{"en":"Does a transaction ID alone prove an operation succeeded?","ar":"هل يثبت معرّف المعاملة وحده نجاح العملية؟"},"options":[{"en":"Always","ar":"دائماً"},{"en":"No, inspect execution outcome","ar":"لا، افحص نتيجة التنفيذ"},{"en":"Only in a browser","ar":"في المتصفح فقط"}],"answer":1,"explanation":{"en":"A submitted transaction can fail or produce an unexpected outcome.","ar":"قد تفشل المعاملة المقدمة أو تنتج نتيجة غير متوقعة."}},{"question":{"en":"Where should this project be practiced?","ar":"أين ينفذ هذا المشروع التدريبي؟"},"options":[{"en":"On a local development chain with test accounts","ar":"على سلسلة تطوير محلية بحسابات اختبار"},{"en":"Directly with real user assets","ar":"مباشرة بأصول مستخدمين حقيقية"},{"en":"In a public document containing private keys","ar":"في مستند عام يحوي مفاتيح خاصة"}],"answer":0,"explanation":{"en":"A disposable local environment supports repeatable learning without real assets.","ar":"تتيح البيئة المحلية القابلة للاستبدال تعلماً متكرراً دون أصول حقيقية."}}]}');
